cat > /tmp/ratecap_test.mjs << 'EOF'
const EVENTS_MAX = 500;
const eventsBuf = [];
let eventSeq = 0;
const RATE_CAP_PER_TYPE = 30;
const RATE_CAP_WINDOW_MS = 60000;
const rateState = new Map();

function flushSuppressed(type, rs) {
  if (!rs || rs.suppressed <= 0) return;
  eventSeq++;
  eventsBuf.push({ seq: eventSeq, ts: 'x', type, msg: `...suppressed ${rs.suppressed} similar ${type} event(s)` });
  if (eventsBuf.length > EVENTS_MAX) eventsBuf.shift();
  rs.suppressed = 0;
}
function sweepStaleRateWindows(now) {
  for (const [type, rs] of rateState) {
    if (rs.suppressed > 0 && now - rs.windowStart >= RATE_CAP_WINDOW_MS) flushSuppressed(type, rs);
  }
}
function pushEvent(type, msg, now) {
  let rs = rateState.get(type);
  if (!rs) { rs = { windowStart: now, count: 0, suppressed: 0 }; rateState.set(type, rs); }
  else if (now - rs.windowStart >= RATE_CAP_WINDOW_MS) { flushSuppressed(type, rs); rs.windowStart = now; rs.count = 0; }
  rs.count++;
  if (rs.count > RATE_CAP_PER_TYPE) { rs.suppressed++; return; }
