  for (const horiz of [0, 0.5, 0.71, 1.0]) {
    const total = Math.hypot(vert, horiz);
    console.log(`  + horiz ${horiz.toFixed(2)} => total ${total.toFixed(3)} ${total > 4.2 ? '(EXCEEDS 4.2)' : '(within 4.2)'}`);
  }
