// Faithful mini-reproduction of mineflayer-pathfinder's real logic (lib/movements.js),
// using REAL block metadata from the installed minecraft-data package.
const mcData = (await import('minecraft-data')).default('1.20.4');

function safe(blockType, blocksToAvoid) {
  const b = mcData.blocks[blockType];
  const boundingBoxEmpty = b.boundingBox === 'empty';
  return boundingBoxEmpty && !blocksToAvoid.has(blockType);
}
function safeToBreak(canDig) { return canDig; } // matches: if (!this.canDig) return false (rest doesn't matter, canDig=false here)
function safeOrBreak(blockType, blocksToAvoid, canDig) {
  let cost = 0; // exclusionStep + entityCost both 0 in our no-exclusion-zone setup
  if (safe(blockType, blocksToAvoid)) return cost;
  if (!safeToBreak(canDig)) return 100;
  return 100; // (unreachable here since canDig=false always returns 100 above, kept for fidelity)
}

const wheatId = mcData.blocksByName.wheat.id;
const farmlandId = mcData.blocksByName.farmland.id;
