cat > /tmp/rawwalk_test.mjs << 'EOF'
// Faithful reproduction of the NEW rawWalkTo control flow (post-fix), with a
// fake bot/world, to verify both required outcomes without touching a live server.
const CROP_BLOCK_NAMES = ['wheat', 'carrots', 'potatoes', 'beetroots'];

function nextCellToward(pos, targetPos) {
  const dx = targetPos.x - pos.x, dz = targetPos.z - pos.z;
  const mag = Math.hypot(dx, dz);
  if (mag < 0.001) return { x: Math.floor(pos.x), y: Math.floor(pos.y), z: Math.floor(pos.z) };
  return { x: Math.floor(pos.x + dx / mag), y: Math.floor(pos.y), z: Math.floor(pos.z + dz / mag) };
}

function makeBot(startPos, world, moveTowardTarget) {
  const pos = { ...startPos };
  return {
    entity: { position: { x: pos.x, y: pos.y, z: pos.z, floored: () => ({ x: Math.floor(pos.x), y: Math.floor(pos.y), z: Math.floor(pos.z) }) } },
    blockAt: (p) => ({ name: world[`${p.x},${p.y},${p.z}`] ?? 'air' }),
    lookAt: async () => {},
    setControlState: (name, on) => { if (name === 'forward' && on && moveTowardTarget) moveTowardTarget(pos); },
    _pos: pos,
  };
}

async function rawWalkToSim(bot, targetPos, ctx, maxPulses = 50) {
  let controlsTouched = false;
  for (let i = 0; i < maxPulses; i++) {
    // reached check (simplified: within 0.6 counts as reached)
    const dx = targetPos.x - bot._pos.x, dz = targetPos.z - bot._pos.z;
    if (Math.hypot(dx, dz) <= 0.6) return { reached: true, controlsTouched };

    const feetName = bot.blockAt(bot.entity.position.floored()).name;
    const aheadCell = nextCellToward(bot.entity.position, targetPos);
    const aheadName = bot.blockAt(aheadCell).name;
    if (CROP_BLOCK_NAMES.includes(feetName) || CROP_BLOCK_NAMES.includes(aheadName)) {
      throw new Error(`rawWalkTo: refusing to bulldoze onto a protected block (feet=${feetName}, ahead=${aheadName})`);
    }
    controlsTouched = true;
    bot.setControlState('forward', true);
  }
  return { reached: false, controlsTouched };
}

// Outcome 1: REFUSED-ON-CROP — target sits beyond a crop tile directly ahead
const world1 = { '5,89,5': 'wheat' };
const bot1 = makeBot({ x: 4.5, y: 89, z: 4.5 }, world1, (p) => { p.x += 0.3; p.z += 0.3; });
try {
  await rawWalkToSim(bot1, { x: 6, y: 89, z: 6 }, {});
  console.log('Outcome 1 FAIL: should have thrown');
} catch (err) {
  console.log('Outcome 1 (refused-on-crop): threw as expected ->', err.message);
  console.log('  controls ever touched before refusal? (should be false on first pulse):', bot1._pos.x === 4.5 ? 'PASS (never moved)' : 'check');
}

// Outcome 2: NORMAL RESCUE UNCHANGED — no crops anywhere, bot reaches goal via pulses
const world2 = {};
const bot2 = makeBot({ x: 4.5, y: 89, z: 4.5 }, world2, (p) => { p.x += 0.4; p.z += 0.4; });
const result2 = await rawWalkToSim(bot2, { x: 6, y: 89, z: 6 }, {});
console.log('Outcome 2 (normal rescue): result =', result2, result2.reached ? 'PASS reached goal via pulses' : 'FAIL');
EOF
node /tmp/rawwalk_test.mjs
rm /tmp/rawwalk_test.mjs

