  } catch (err) {
    const now = bot.blockAt(pos);
    if (!now || now.name !== expectedName) {
      ctx?.log?.(
        'warn',
        `safeDig: dig() errored/timed out but world state shows the block is gone at ${posKey(pos)} — treating as success (${err?.message ?? err})`
