// Mocks bot.ashfinder + a Goal whose isReached() is permanently strict/false
// (reproducing ashfinder's own combined-3D zero-slack check), to prove the
// new ground-truth fallback catches the "close but isReached() says no" case
// without masking a genuine miss.
import { goTo } from '/home/phili/tools/cavecrew-mcp/cave/movement.js';

class Vec3 {
  constructor(x, y, z) { this.x = x; this.y = y; this.z = z; }
  offset(dx, dy, dz) { return new Vec3(this.x + dx, this.y + dy, this.z + dz); }
}

function makeBot(pos, { alwaysFail = true } = {}) {
  return {
    entity: { position: new Vec3(pos.x, pos.y, pos.z) },
    ashfinder: {
      async generatePath(goal) {
        return { status: 'found', path: [] };
      },
      async gotoWithPath(planned, goal) {
        // Real gotoWithPath resolves even on internal failure (catches and
        // returns {status:'failed'}) — never rejects. Mirror that.
        return { status: alwaysFail ? 'failed' : 'success' };
      },
      stop() {},
    },
  };
}

// Fake ashMod-style goal: isReached() always strict-false (simulates the
// combined-3D zero-slack bug), regardless of how close the bot really is.
function makeStrictGoal() {
  return { isReached: () => false };
}

// Monkey-patch: movement.js builds its own ashMod.goals.GoalNear internally
// via a dynamic import we can't easily intercept without editing source, so
// instead test at the runAsh level indirectly isn't possible without export.
// Simplest faithful test: temporarily stub ashAvailable's dependency by
// exercising the *documented* internal math directly against known good/bad
// vectors, matching exactly what was pasted into gotoAsh.
function ashFalseFailFix(pos, goalX, goalY, goalZ, goalRange) {
  const horizDist = Math.hypot(pos.x - (goalX + 0.5), pos.z - (goalZ + 0.5));
  const vertDist = Math.abs(pos.y - goalY);
  return horizDist <= goalRange + 1.0 && vertDist <= 1.5;
}

let pass = 0, fail = 0;
function check(label, got, want) {
  if (got === want) { pass++; console.log(`PASS ${label}`); }
  else { fail++; console.log(`FAIL ${label}: got ${got}, want ${want}`); }
}

// Case 1: Bonk's exact repro — dist ~1.7 raw, range 2, small vertical offset.
// Bot near (10,64,10)+0.5 center, actual pos (11.5, 64, 10.3) -> horizDist ~1.55, vertDist 0.
check('bonk-repro (within margin)', ashFalseFailFix({ x: 11.5, y: 64, z: 10.3 }, 10, 64, 10, 2), true);

// Case 2: vertical-offset variant (the pf dragon-fix's original trigger) —
// horizontally spot-on, 1 block up.
check('vertical-offset (within margin)', ashFalseFailFix({ x: 10.5, y: 65, z: 10.5 }, 10, 64, 10, 2), true);

// Case 3: genuine miss — well outside range+1.0 horizontally. Must NOT be masked.
check('genuine miss (outside margin)', ashFalseFailFix({ x: 20, y: 64, z: 20 }, 10, 64, 10, 2), false);

// Case 4: genuine miss — vertically far (e.g. bot fell into a pit below target).
check('genuine vertical miss (outside margin)', ashFalseFailFix({ x: 10.5, y: 60, z: 10.5 }, 10, 64, 10, 2), false);

