            await bot.autoEat.eat({ food: bestFood, offhand: false });
          } else {
            await bot.equip(bestFood, 'hand');
            await bot.consume();
          }
          ate = true;
        } catch (err) {
          ctx.log?.('warn', `emergencySeal: eat attempt ${attempt}/2 failed: ${err.message}`);
