// Faithful extraction of the fixed retry-loop shape from emergencySeal
// (skills.js ~3276-3307), with stub findBestFoodItem/eat to prove:
// 1. findBestFoodItem is re-invoked EVERY attempt (fresh, not reused).
// 2. it stops cleanly (break, no throw) when food runs out between attempts.
// 3. a successful eat on attempt 2 (after attempt 1's transient failure)
//    uses the SECOND fresh lookup, not the first.
async function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function runScenario(label, foodSequence, eatShouldThrowOnAttempt) {
  let callCount = 0;
  const findBestFoodItem = () => {
    const v = foodSequence[callCount] ?? null;
    callCount++;
    return v;
  };
  const seenByEat = [];
  let ate = false;
  for (let attempt = 1; attempt <= 2 && !ate; attempt++) {
    const foodNow = findBestFoodItem();
    if (!foodNow) break;
    seenByEat.push(foodNow);
    try {
      if (attempt === eatShouldThrowOnAttempt) throw new Error('simulated transient eat failure');
      ate = true;
    } catch (err) {
      if (attempt < 2) await sleep(1);
    }
  }
  console.log(label, '-> ate:', ate, 'lookups:', callCount, 'itemsSeenByEat:', JSON.stringify(seenByEat));
  return { ate, callCount, seenByEat };
}

(async () => {
  let pass = 0, fail = 0;
  const check = (cond, msg) => { if (cond) { pass++; console.log('PASS', msg); } else { fail++; console.log('FAIL', msg); } };

  // Scenario A: attempt 1 fails (stale-slot race simulated), attempt 2 uses
  // a DIFFERENT (fresh) item object and succeeds.
  const a = await runScenario('A: fail-then-fresh-succeed', ['bread#slot9-stale', 'bread#slot4-fresh'], 1);
  check(a.ate === true, 'A: eventually ate');
  check(a.callCount === 2, 'A: findBestFoodItem called twice (fresh each attempt)');
  check(a.seenByEat[0] !== a.seenByEat[1], 'A: attempt 2 used a DIFFERENT (fresh) item, not the stale attempt-1 one');

  // Scenario B: food vanishes between attempts (genuinely out) -> breaks
  // cleanly, no throw, no infinite loop.
  const b = await runScenario('B: out-of-food between attempts', ['bread#slot9', null], 1);
  check(b.ate === false, 'B: did not eat (correct)');
  check(b.callCount === 2, 'B: still re-checked on attempt 2 before giving up');
  check(b.seenByEat.length === 1, 'B: eat() never called with a null item');

  // Scenario C: first attempt succeeds outright -> only ONE fresh lookup.
  const c = await runScenario('C: succeed first try', ['bread#slot9'], 0);
  check(c.ate === true, 'C: ate on first try');
  check(c.callCount === 1, 'C: only one lookup needed, no wasted second call');

  console.log((pass)+' passed, '+(fail)+' failed');
  process.exit(fail ? 1 : 0);
})();
"

