// Dry-run test for movement.js's new hard vertical-drop guard, exercised
// through the REAL public goTo() (engine:'pf') with a scripted mock bot —
// not a re-implementation of the detection math, the actual wired code.
import { EventEmitter } from 'node:events';
import { goTo } from '/home/phili/tools/cavecrew-mcp/cave/movement.js';

function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

// Builds a mock bot whose bot.pathfinder.goto() plays back a scripted
// sequence of {y, onGround, velocityY} frames as real physicsTick events,
// one every ~5ms (fast test), and stops EARLY the instant setGoal(null) is
// called after the run starts — mirroring real mineflayer-pathfinder's
// actual behavior (a live setGoal(null) target-clear steers the goto()
// promise to settle almost immediately, which is exactly what the existing
// retry-loop code already depends on).
function makeMockBot(frames) {
  const bot = new EventEmitter();
  let goalCleared = false;
  bot.entity = { position: { x: 10, y: frames[0].y, z: 10 }, velocity: { x: 0, y: 0, z: 0 }, onGround: frames[0].onGround };
  bot.pathfinder = {
    setGoal(g) {
      if (g === null) goalCleared = true;
    },
    async goto(goal) {
      for (let i = 1; i < frames.length; i++) {
        if (goalCleared) throw new Error('pathfinder: goal cleared mid-flight (simulated stop)');
        await sleep(3);
        const f = frames[i];
        bot.entity.position = { x: 10, y: f.y, z: 10 };
        bot.entity.velocity = { x: 0, y: f.velocityY, z: 0 };
        bot.entity.onGround = f.onGround;
        bot.emit('physicsTick');
      }
      if (goalCleared) throw new Error('pathfinder: goal cleared mid-flight (simulated stop)');
      return {};
    },
  };
  return bot;
}

function genuineFallFrames(startY, dropBlocks, steps) {
  // Simulates real MC gravity roughly: velocity.y grows more negative each
  // tick, position falls accordingly, never lands (onGround stays false).
  const frames = [{ y: startY, onGround: true, velocityY: 0 }];
  let y = startY, vy = 0;
  const perStep = dropBlocks / steps;
  for (let i = 0; i < steps; i++) {
    vy -= 0.4; // accelerating fall
    y -= perStep;
    frames.push({ y, onGround: false, velocityY: vy });
  }
  return frames;
}

function normalStepDownFrames(startY) {
  // A legit 1-block step-down: airborne for exactly one tick, then lands.
  return [
    { y: startY, onGround: true, velocityY: 0 },
    { y: startY - 1, onGround: false, velocityY: -0.3 },
    { y: startY - 1, onGround: true, velocityY: 0 },
  ];
}

function jumpArcFrames(startY) {
  // A legit jump: up ~1.25 then back down to the SAME level, never a real drop.
  return [
    { y: startY, onGround: true, velocityY: 0 },
    { y: startY + 0.6, onGround: false, velocityY: 0.4 },
    { y: startY + 1.0, onGround: false, velocityY: 0.1 },
    { y: startY + 0.6, onGround: false, velocityY: -0.3 },
    { y: startY, onGround: true, velocityY: 0 },
  ];
}

function teleportSnapFrames(startY) {
  // A single-tick 30-block position correction — the exact false-reach
  // shape from Ook's incident (position resynced far below in one jump).
  return [
    { y: startY, onGround: true, velocityY: 0 },
    { y: startY - 30, onGround: false, velocityY: 0 }, // snap, velocity not yet updated
  ];
}

let pass = 0, fail = 0;
function check(label, cond) {
  if (cond) { pass++; console.log('PASS', label); }
  else { fail++; console.log('FAIL', label); }
}

(async () => {
  // Case 1: genuine multi-block freefall (12 blocks over 20 ticks, like a
  // real false-reach fall into a cave pocket) — MUST abort.
  {
    const bot = makeMockBot(genuineFallFrames(89, 12, 20));
    let threw = null;
    try {
      await goTo(bot, { x: 10, y: 66, z: 10, range: 2, timeoutMs: 5000, engine: 'pf' }, {});
    } catch (err) {
      threw = err;
    }
    check('genuine freefall: goTo() throws', !!threw);
    check('genuine freefall: error names the fall guard', /fall guard/i.test(threw?.message ?? ''));
  }

  // Case 2: normal 1-block step-down — must NOT abort (goto proceeds to
  // its own normal resolution; no fall-guard error).
  {
    const bot = makeMockBot(normalStepDownFrames(89));
    let threw = null;
    try {
      await goTo(bot, { x: 10, y: 88, z: 10, range: 2, timeoutMs: 5000, engine: 'pf' }, {});
    } catch (err) {
      threw = err;
    }
    check('normal step-down: no fall-guard abort', !threw || !/fall guard/i.test(threw.message));
  }

  // Case 3: normal jump arc (up then back down to start) — must NOT abort.
  {
    const bot = makeMockBot(jumpArcFrames(89));
    let threw = null;
    try {
      await goTo(bot, { x: 10, y: 89, z: 10, range: 2, timeoutMs: 5000, engine: 'pf' }, {});
    } catch (err) {
      threw = err;
    }
    check('jump arc: no fall-guard abort', !threw || !/fall guard/i.test(threw.message));
  }

  // Case 4: single-tick teleport-class snap (30 blocks in one tick, zero
  // velocity yet) — MUST abort via the tick-jump signal, not velocity.
  {
    const bot = makeMockBot(teleportSnapFrames(89));
    let threw = null;
    try {
      await goTo(bot, { x: 10, y: 60, z: 10, range: 2, timeoutMs: 5000, engine: 'pf' }, {});
    } catch (err) {
      threw = err;
    }
    check('teleport snap: goTo() throws', !!threw);
    check('teleport snap: error names the fall guard', /fall guard/i.test(threw?.message ?? ''));
  }

  console.log(`\n${pass} passed, ${fail} failed`);
  process.exit(fail === 0 ? 0 : 1);
})();
NODEEOF
