// call path at all.
import { EventEmitter } from 'node:events';
import { gotoLoopPf } from '/home/phili/tools/cavecrew-mcp/cave/movement.js';
import pathfinderPkg from 'mineflayer-pathfinder';
const { goals: pfGoals } = pathfinderPkg;

function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

function makeMockBot(frames) {
  const bot = new EventEmitter();
  let goalCleared = false;
  bot.entity = { position: { x: 10, y: frames[0].y, z: 10 }, velocity: { x: 0, y: 0, z: 0 }, onGround: frames[0].onGround };
  bot.pathfinder = {
    setGoal(g) { if (g === null) goalCleared = true; },
    async goto(goal) {
      for (let i = 1; i < frames.length; i++) {
        if (goalCleared) throw new Error('pathfinder: goal cleared mid-flight (simulated stop)');
        await sleep(3);
        const f = frames[i];
        bot.entity.position = { x: 10, y: f.y, z: 10 };
        bot.entity.velocity = { x: 0, y: f.velocityY, z: 0 };
        bot.entity.onGround = f.onGround;
        bot.emit('physicsTick');
      }
      if (goalCleared) throw new Error('pathfinder: goal cleared mid-flight (simulated stop)');
      return {};
    },
  };
  return bot;
}

function genuineFallFrames(startY, dropBlocks, steps) {
  const frames = [{ y: startY, onGround: true, velocityY: 0 }];
  let y = startY, vy = 0;
  const perStep = dropBlocks / steps;
  for (let i = 0; i < steps; i++) {
    vy -= 0.4;
    y -= perStep;
    frames.push({ y, onGround: false, velocityY: vy });
  }
  return frames;
}

function normalSingleCellStepFrames(startY) {
  // digCorridorStep's own real shape: a range:0 single-cell step, 1 block
  // forward at the SAME y (corridor stays level) — one tick airborne max.
  return [
    { y: startY, onGround: true, velocityY: 0 },
    { y: startY, onGround: false, velocityY: -0.08 },
    { y: startY, onGround: true, velocityY: 0 },
  ];
}

let pass = 0, fail = 0;
function check(label, cond) {
  if (cond) { pass++; console.log('PASS', label); } else { fail++; console.log('FAIL', label); }
}

(async () => {
  // Case 1: genuine multi-block freefall DURING a direct gotoLoopPf() call
  // (exactly what digCorridorStep invokes via skills.js's gotoLoop()) — must abort.
  {
    const bot = makeMockBot(genuineFallFrames(54, 17, 25)); // mirrors Grog's actual 17-block corridor fall
    const goal = new pfGoals.GoalNear(10, 37, 10, 0);
    let threw = null;
    try {
      await gotoLoopPf(bot, goal, { timeoutMs: 5000, maxAttempts: 2 }, {});
    } catch (err) {
      threw = err;
    }
    check('digCorridorStep-shape freefall: gotoLoopPf() throws', !!threw);
    check('digCorridorStep-shape freefall: error names the fall guard', /fall guard/i.test(threw?.message ?? ''));
  }

  // Case 2: normal single-cell corridor step (digCorridorStep's actual real
  // shape) — must NOT abort.
  {
    const bot = makeMockBot(normalSingleCellStepFrames(54));
    const goal = new pfGoals.GoalNear(11, 54, 10, 0);
    let threw = null;
    try {
      await gotoLoopPf(bot, goal, { timeoutMs: 5000, maxAttempts: 2 }, {});
    } catch (err) {
      threw = err;
    }
    check('normal corridor step: no fall-guard abort', !threw || !/fall guard/i.test(threw.message));
  }

  console.log(`\n${pass} passed, ${fail} failed`);
  process.exit(fail === 0 ? 0 : 1);
})();
