let preexistingJavaPids = new Set();

function log(line) {
  process.stdout.write(`[${new Date().toISOString()}] [${NAME}] ${line}\n`);
}

// -------------------------------------------------------------- console -----
function sendConsole(cmd) {
  if (!child || !child.stdin || child.stdin.destroyed) throw new Error('launcher not running');
  log(`SEND: ${cmd}`);
  child.stdin.write(cmd + '\n');
}

// A `#`-prefixed chat line is intercepted CLIENT-SIDE by Baritone before it
// leaves for the server, so this never produces real server chat.
function sendChat(msg) {
  // hmc-specifics rejects `msg` before the client is in a world
  // ("You need to be ingame to send a message!"), so don't bother.
  if (!state.connected) throw new Error('not in world');
  sendConsole(`msg ${msg}`);
}

// --------------------------------------------------------- preflight --------
function readProps(file) {
  const out = new Map();
  if (!fs.existsSync(file)) return out;
  for (const raw of fs.readFileSync(file, 'utf8').split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith('#') || line.startsWith('!')) continue;
    const i = line.indexOf('=');
    if (i === -1) continue;
    out.set(line.slice(0, i).trim(), line.slice(i + 1));
  }
  return out;
}

