function preflight() {
  const missing = [];
  if (!fs.existsSync(JAVA)) missing.push(`java: ${JAVA}`);
  if (!fs.existsSync(path.join(BOT_DIR, LAUNCHER_JAR))) missing.push(`launcher: ${path.join(BOT_DIR, LAUNCHER_JAR)}`);
  if (!fs.existsSync(path.join(MC_INSTALL, 'versions', 'fabric-loader-0.19.3-1.21.11'))) {
    missing.push(`fabric version: ${path.join(MC_INSTALL, 'versions', 'fabric-loader-0.19.3-1.21.11')}`);
  }

  fs.mkdirSync(MODS_DIR, { recursive: true });
  for (const mod of PINNED_MODS) {
    const dest = path.join(MODS_DIR, mod.name);
    if (fs.existsSync(dest)) continue;
    const src = mod.sources.find((s) => fs.existsSync(s));
    if (!src) { missing.push(`mod (no pinned source on disk): ${mod.name}`); continue; }
    fs.copyFileSync(src, dest);
    log(`installed pinned mod ${mod.name} <- ${src}`);
  }

  // Any mod in the per-instance mods dir that is not on the pinned list is a
  // version-drift hazard (e.g. an auto-installed "-latest" specifics jar
  // sitting next to the pinned one). Refuse to boot rather than guess.
  const pinnedNames = new Set(PINNED_MODS.map((m) => m.name));
  for (const f of fs.readdirSync(MODS_DIR)) {
    if (f.endsWith('.jar') && !pinnedNames.has(f)) missing.push(`UNPINNED mod present: ${path.join(MODS_DIR, f)}`);
  }

  if (missing.length) {
    console.error('FATAL preflight — pinned artifacts missing/unexpected (this runner never downloads):');
    for (const m of missing) console.error('  - ' + m);
    process.exit(1);
  }
  log(`preflight ok — mods: ${[...pinnedNames].join(', ')}`);
}

