    // can still path THROUGH the FEL box.
    log(`WATCHDOG: position ${x},${y},${z} inside FEL no-go box -- STOP`);
    try { sendChat('#stop'); } catch {}
    state.aborted = 'nogo';
    state.task = null;
  }
}

function handleLogLine(line) {
  if (!state.connected && JOIN_RE.test(line)) {
    state.connected = true;
    state.phase = 'in-world';
    state.joinedAt = Date.now();
    log('JOIN detected');
  }
  const c = line.match(CHAT_RE);
  if (c) {
    chatLog.push(c[1].trim());
    if (chatLog.length > CHAT_LOG_MAX) chatLog.shift();
  }
  const m = line.match(CHAT_BARITONE_RE);
  if (!m) return;
