if (req.method === 'POST' && url === '/stop') {
  sendChat('#stop');
  state.task = null;
  return reply(res, 200, { ok: true });
}

// Whitelisted read-only baritone words (client-side only, never server chat).
if (req.method === 'POST' && url === '/console') {
  const cmd = String(body.cmd || '').trim();
  if (!SAFE_CONSOLE_CHAT.has(cmd)) return reply(res, 403, { error: 'command not whitelisted', allowed: [...SAFE_CONSOLE_CHAT] });
  if (cmd === '#goal') posPollPending = true;
  sendChat(cmd);
  return reply(res, 200, { ok: true, sent: cmd });
}

if (req.method === 'POST' && url === '/disconnect') {
  try { sendChat('#stop'); } catch {}
  setTimeout(() => { try { sendConsole('disconnect'); } catch {} }, 500);
  state.task = null;
  state.connected = false;
  state.phase = 'disconnected';
  if (posPollTimer) clearInterval(posPollTimer);
  return reply(res, 200, { ok: true });
}

if (req.method === 'POST' && url === '/relog') {
  try {
    sendConsole('disconnect');
    setTimeout(() => sendConsole(`connect ${MC_HOST} ${MC_PORT}`), 3000);
    return reply(res, 200, { ok: true, mode: 'soft' });
  } catch {
    killTree(() => boot());
    return reply(res, 200, { ok: true, mode: 'full-relaunch' });
  }
}

if (req.method === 'POST' && url === '/shutdown') {
  reply(res, 200, { ok: true, shuttingDown: true });
  state.phase = 'shutting-down';
  if (posPollTimer) clearInterval(posPollTimer);

