168	// ------------------------------------------------------- FEL no-go ----------
169	const NOGO = { x: -3, z: 4, r: 15, pad: 5 }; // padded box: x [-23,17], z [-16,24], all y
170	function inNoGo(x, z) {
171	  return x >= NOGO.x - NOGO.r - NOGO.pad && x <= NOGO.x + NOGO.r + NOGO.pad
172	      && z >= NOGO.z - NOGO.r - NOGO.pad && z <= NOGO.z + NOGO.r + NOGO.pad;
173	}
