220	// --------------------------------------------------------- preflight --------
221	function readProps(file) {
222	  const out = new Map();
223	  if (!fs.existsSync(file)) return out;
224	  for (const raw of fs.readFileSync(file, 'utf8').split(/\r?\n/)) {
225	    const line = raw.trim();
226	    if (!line || line.startsWith('#') || line.startsWith('!')) continue;
227	    const i = line.indexOf('=');
228	    if (i === -1) continue;
229	    out.set(line.slice(0, i).trim(), line.slice(i + 1));
230	  }
231	  return out;
232	}
