234	function writeHmcConfig() {
235	  fs.mkdirSync(HMC_DIR, { recursive: true });
236	  const props = readProps(HMC_CONFIG);
237	  // Forward slashes: java.util.Properties treats "\" as an escape character.
238	  props.set('hmc.gamedir', GAME_DIR.replace(/\\/g, '/'));
239	  props.set('hmc.game.dir.for.each.version', 'false');
240	  props.set('hmc.offline.username', NAME);
241	  // Launcher-side JLine: harmless, keeps the launcher console sane over a pipe.
242	  // (The load-bearing one is -Dhmc.jline.enabled=false on the CHILD jvm, in
243	  // JVM_ARGS above — config.properties does not reach the child.)
244	  props.set('hmc.jline.dumb.when.no.console', 'true');
245	  if (!props.has('hmc.java.versions')) props.set('hmc.java.versions', JAVA.replace(/\\/g, '/'));
246	  const body = [...props.entries()].map(([k, v]) => `${k}=${v}`).join('\n') + '\n';
247	  fs.writeFileSync(HMC_CONFIG, body);
248	  log(`hmc.gamedir=${props.get('hmc.gamedir')}`);
249	}
