251	function preflight() {
252	  const missing = [];
253	  if (!fs.existsSync(JAVA)) missing.push(`java: ${JAVA}`);
254	  if (!fs.existsSync(path.join(BOT_DIR, LAUNCHER_JAR))) missing.push(`launcher: ${path.join(BOT_DIR, LAUNCHER_JAR)}`);
255	  if (!fs.existsSync(path.join(MC_INSTALL, 'versions', 'fabric-loader-0.19.3-1.21.11'))) {
256	    missing.push(`fabric version: ${path.join(MC_INSTALL, 'versions', 'fabric-loader-0.19.3-1.21.11')}`);
257	  }
258	
259	  fs.mkdirSync(MODS_DIR, { recursive: true });
260	  for (const mod of PINNED_MODS) {
261	    const dest = path.join(MODS_DIR, mod.name);
262	    if (fs.existsSync(dest)) continue;
263	    const src = mod.sources.find((s) => fs.existsSync(s));
264	    if (!src) { missing.push(`mod (no pinned source on disk): ${mod.name}`); continue; }
265	    fs.copyFileSync(src, dest);
266	    log(`installed pinned mod ${mod.name} <- ${src}`);
267	  }
268	
269	  // Any mod in the per-instance mods dir that is not on the pinned list is a
270	  // version-drift hazard (e.g. an auto-installed "-latest" specifics jar
271	  // sitting next to the pinned one). Refuse to boot rather than guess.
272	  const pinnedNames = new Set(PINNED_MODS.map((m) => m.name));
273	  for (const f of fs.readdirSync(MODS_DIR)) {
274	    if (f.endsWith('.jar') && !pinnedNames.has(f)) missing.push(`UNPINNED mod present: ${path.join(MODS_DIR, f)}`);
275	  }
276	
277	  if (missing.length) {
278	    console.error('FATAL preflight — pinned artifacts missing/unexpected (this runner never downloads):');
279	    for (const m of missing) console.error('  - ' + m);
280	    process.exit(1);
281	  }
282	  log(`preflight ok — mods: ${[...pinnedNames].join(', ')}`);
283	}
