285	function writeBaritoneSettings() {
286	  fs.mkdirSync(path.dirname(SETTINGS_PATH), { recursive: true });
287	  fs.writeFileSync(SETTINGS_PATH, [
288	    // CHIEF RULING 2026-09-01: legitMine OFF — parity with the mineflayer
289	    // fleet's own /mine, which already finds buried ore via chunk-data scans.
290	    // Visible-only was holding Baritone to a stricter standard than the rest
291	    // of the fleet, not a stricter no-cheat law. See cave/BARITONE.md 5a.
292	    'legitMine false',
293	    'allowDownward false',
294	    'minYLevelWhileMining -54',
295	    'maxYLevelWhileMining 95',
296	    // FIELD-VERIFIED 1.17.0 format: bare comma-separated block ids, NO square
297	    // brackets. The bracketed form from the blueprint makes baritone log
298	    // "Unable to parse line ... Invalid block name [chest" and drop the whole
299	    // setting, silently losing the protection.
300	    'blocksToDisallowBreaking chest,trapped_chest,crafting_table,furnace,blast_furnace,oak_sign,oak_wall_sign,barrel',
301	    'chatDebug true',
302	    '',
303	  ].join('\n'));
304	}
