306	// ------------------------------------------------------------- window -------
307	// Hide the real GLFW window. We do NOT run -lwjgl (see header), so a real
308	// window exists; fleet law is no visible client. Identify it as "a java
309	// process that did not exist before we spawned the launcher" — never touch the
310	// server JVM or any other pre-existing java process.
311	function snapshotJavaPids() {
312	  return new Promise((resolve) => {
313	    execFile('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command',
314	      "Get-Process java,javaw -ErrorAction SilentlyContinue | ForEach-Object { $_.Id }"],
315	      (err, stdout) => {
316	        const pids = new Set(String(stdout || '').split(/\r?\n/).map((s) => s.trim()).filter(Boolean));
317	        resolve(pids);
318	      });
319	  });
320	}
