322	function hideGameWindow() {
323	  if (SHOW_WINDOW) return;
324	  const skip = [...preexistingJavaPids, String(child?.pid ?? 0)].join(',');
325	  const ps = `
326	$skip = @(${skip.split(',').filter(Boolean).map((p) => p).join(',') || '0'})
327	Add-Type @"
328	using System;
329	using System.Runtime.InteropServices;
330	public class Win32HideBari {
331	  [DllImport("user32.dll")] public static extern bool ShowWindowAsync(IntPtr hWnd, int nCmdShow);
332	}
333	"@
334	Get-Process java,javaw -ErrorAction SilentlyContinue | Where-Object { $skip -notcontains $_.Id -and $_.MainWindowHandle -ne 0 } | ForEach-Object {
335	  [Win32HideBari]::ShowWindowAsync($_.MainWindowHandle, 0) | Out-Null
336	  "hid pid=$($_.Id)"
337	}`;
338	  execFile('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', ps], (err, stdout) => {
339	    if (stdout && stdout.trim()) log(`WINDOW: ${stdout.trim()}`);
340	  });
341	}
