343	// --------------------------------------------------------------- boot -------
344	async function boot() {
345	  fs.mkdirSync(BOT_DIR, { recursive: true });
346	  fs.mkdirSync(GAME_DIR, { recursive: true });
347	  writeHmcConfig();
348	  preflight();
349	  writeBaritoneSettings();
350	
351	  // Fresh state wire: drop the previous session's latest.log so the tail can
352	  // start at offset 0 with no risk of replaying stale [CHAT] lines.
353	  try { if (fs.existsSync(LOG_PATH)) fs.unlinkSync(LOG_PATH); } catch { /* held open, tail handles it */ }
354	
355	  preexistingJavaPids = await snapshotJavaPids();
356	  log(`pre-existing java pids (never touched): ${[...preexistingJavaPids].join(',') || 'none'}`);
357	
358	  child = spawn(JAVA, ['-jar', LAUNCHER_JAR], {
359	    cwd: BOT_DIR,
360	    stdio: ['pipe', 'pipe', 'pipe'],
361	    windowsHide: true,
362	  });
363	  log(`launcher pid=${child.pid}`);
364	  try { fs.mkdirSync(path.join(ROOT, 'pids'), { recursive: true }); fs.writeFileSync(path.join(ROOT, 'pids', `${NAME}.pid`), String(child.pid)); } catch {}
365	
366	  child.stdout.on('data', (d) => handleLauncherOut(String(d)));
367	  child.stderr.on('data', (d) => process.stderr.write(`[hmc-err] ${d}`));
368	  child.on('exit', (code, sig) => {
369	    log(`launcher exited code=${code} sig=${sig}`);
370	    state.connected = false;
371	    state.phase = 'dead';
372	    child = null;
373	  });
374	
375	  startLogTail();
376	
377	  const hideTimer = setInterval(hideGameWindow, 3000);
378	  setTimeout(() => clearInterval(hideTimer), 5 * 60 * 1000);
379	
380	  setTimeout(() => {
381	    state.phase = 'launching';
382	    // PROVEN LINE: no -lwjgl, no --quickPlayMultiplayer, jline off on the child.
383	    sendConsole(`launch ${HMC_LAUNCH_TARGET} -offline --jvm "${JVM_ARGS}"`);
384	
385	    setTimeout(() => {
386	      state.phase = 'connecting';
387	      // hmc-specifics ConnectCommand: raw line `connect <host> [port]`
388	      // (args[1]=host, args[2]=port; verified by javap on ConnectCommand.class)
389	      sendConsole(`connect ${MC_HOST} ${MC_PORT}`);
390	      setTimeout(() => {
391	        try { sendChat('#set chatDebug true'); } catch {}
392	        startPosPoll();
393	      }, CHATDEBUG_DELAY_MS);
394	    }, CONNECT_DELAY_MS);
395	  }, LAUNCH_DELAY_MS);
396	}
