398	function handleLauncherOut(text) {
399	  process.stdout.write(`[hmc] ${text}`);
400	  // The launcher relays the game's stdout, so baritone's own path chatter
401	  // ("Path goes for N blocks") shows up here too.
402	  for (const line of text.split(/\r?\n/)) {
403	    if (!line.trim()) continue;
404	    if (/Path goes for|Baritone|\[B\]/i.test(line)) state.lastBaritoneLine = line.trim();
405	  }
406	}
