408	// ------------------------------------------------------------ log tail ------
409	function startLogTail() {
410	  if (logWatchTimer) clearInterval(logWatchTimer);
411	  logOffset = 0;
412	  let lastSize = -1;
413	  logWatchTimer = setInterval(() => {
414	    try {
415	      const stat = fs.statSync(LOG_PATH);
416	      if (stat.size < lastSize) logOffset = 0; // rotated (relog) -> reopen from start
417	      lastSize = stat.size;
418	      if (stat.size > logOffset) {
419	        const fd = fs.openSync(LOG_PATH, 'r');
420	        const buf = Buffer.alloc(stat.size - logOffset);
421	        fs.readSync(fd, buf, 0, buf.length, logOffset);
422	        fs.closeSync(fd);
423	        logOffset = stat.size;
424	        for (const raw of buf.toString('utf8').split('\n')) {
425	          // latest.log is CRLF and the vanilla chat logger embeds ANSI SGR
426	          // colour codes INSIDE the "[Baritone]" tag, e.g.
427	          //   [CHAT] \e[m\e[38;5;5m[\e[38;5;13mBaritone\e[38;5;5m]\e[0m ...
428	          // Both must go before any regex, or "[Baritone]" never matches and
429	          // a trailing \r defeats every $-anchored pattern.
430	          const line = raw.replace(/\x1b\[[0-9;]*[A-Za-z]/g, '').replace(/\r/g, '');
431	          if (line.trim()) handleLogLine(line);
432	        }
433	      }
434	    } catch { /* not created yet */ }
435	  }, 500);
436	}
437	
438	const CHAT_RE = /\[CHAT\]\s*(.*)$/;
439	const CHAT_BARITONE_RE = /\[CHAT\].*?\[(?:Baritone|B)\]\s*(.+)/;
440	// Baritone GoalBlock toString, e.g. "GoalBlock{x=11,y=94,z=48}"
441	const GOALBLOCK_RE = /GoalBlock\{x=(-?\d+),\s*y=(-?\d+),\s*z=(-?\d+)\}/;
442	// BetterBlockPos / generic "(x, y, z)" triple from chatDebug path lines
443	const POS_RE = /\((-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?)\)/;
444	// NOT plain "[CHAT]" — baritone prints settings-parse chatter to the local HUD
445	// while still on the title screen, which false-positives the join.
446	const JOIN_RE = /Connecting to |logged in with entity id|\[System\] \[CHAT\]/i;
447	
448	function setPosition(x, y, z, source) {
449	  state.position = { x, y, z };
450	  state.positionSource = source;
451	  if (inNoGo(x, z)) {
452	    // Layer 2 watchdog. Baritone has no native keep-out zone, so a legal goto
453	    // can still path THROUGH the FEL box.
454	    log(`WATCHDOG: position ${x},${y},${z} inside FEL no-go box -- STOP`);
455	    try { sendChat('#stop'); } catch {}
456	    state.aborted = 'nogo';
457	    state.task = null;
458	  }
459	}
460	
461	function handleLogLine(line) {
462	  if (!state.connected && JOIN_RE.test(line)) {
463	    state.connected = true;
464	    state.phase = 'in-world';
465	    state.joinedAt = Date.now();
466	    log('JOIN detected');
467	  }
468	  const c = line.match(CHAT_RE);
469	  if (c) {
470	    chatLog.push(c[1].trim());
471	    if (chatLog.length > CHAT_LOG_MAX) chatLog.shift();
472	  }
473	  const m = line.match(CHAT_BARITONE_RE);
474	  if (!m) return;
475	  state.lastBaritoneLine = m[1].trim();
476	
477	  const g = m[1].match(GOALBLOCK_RE);
478	  if (g && posPollPending) {
479	    posPollPending = false;
480	    setPosition(parseInt(g[1], 10), parseInt(g[2], 10), parseInt(g[3], 10), 'goal-poll');
481	    return;
482	  }
483	  const p = m[1].match(POS_RE);
484	  if (p) setPosition(parseFloat(p[1]), parseFloat(p[2]), parseFloat(p[3]), 'chatDebug');
485	}
486	
487	// Position poll. `#goal` with no args sets baritone's goal to the player's
488	// CURRENT position and echoes it back — a clean position read. It mutates the
489	// goal, so it is only ever fired while IDLE; during a task the position comes
490	// from chatDebug path lines instead. Never sends anything to server chat.
491	function startPosPoll() {
492	  if (posPollTimer) clearInterval(posPollTimer);
493	  posPollTimer = setInterval(() => {
494	    if (!state.connected || state.task || !child) return;
495	    try { posPollPending = true; sendChat('#goal'); } catch {}
496	  }, 4000);
497	}
498	
499	// ------------------------------------------------------------- shutdown ----
500	function killTree(cb) {
501	  const pid = child?.pid;
502	  const known = new Set(preexistingJavaPids);
503	  const skip = [...known].join(',') || '0';
504	  const ps = `
505	$skip = @(${skip})
506	Get-Process java,javaw -ErrorAction SilentlyContinue | Where-Object { $skip -notcontains $_.Id } | ForEach-Object {
507	  "killing pid=$($_.Id)"
508	  Stop-Process -Id $_.Id -Force -ErrorAction SilentlyContinue
509	}`;
510	  try { if (pid) process.kill(pid); } catch {}
511	  execFile('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', ps], (e, out) => {
512	    if (out && out.trim()) log(`KILL: ${out.trim()}`);
513	    cb && cb();
514	  });
515	}
