517	// ----------------------------------------------------------------- HTTP -----
518	function reply(res, code, obj) {
519	  res.writeHead(code, { 'Content-Type': 'application/json' });
520	  res.end(JSON.stringify(obj));
521	}
522	
523	const SAFE_CONSOLE_CHAT = new Set(['#eta', '#proc', '#goal', '#version', '#pause', '#resume']);
524	
525	function route(req, res, body) {
526	  const url = req.url.split('?')[0];
527	
528	  if (req.method === 'GET' && url === '/status') {
529	    return reply(res, 200, {
530	      name: NAME,
531	      position: state.position,
532	      positionSource: state.positionSource,
533	      task: state.task,
534	      lastBaritoneLine: state.lastBaritoneLine,
535	      connected: state.connected,
536	      phase: state.phase,
537	      uptime: Date.now() - state.bootedAt,
538	      joinedAt: state.joinedAt,
539	      aborted: state.aborted,
540	      gameDir: state.gameDir,
541	      launcherPid: child?.pid ?? null,
542	    });
543	  }
544	
545	  if (req.method === 'GET' && url === '/log') {
546	    const n = Number(new URL(req.url, 'http://x').searchParams.get('tail') || 40);
547	    return reply(res, 200, { lines: chatLog.slice(-n) });
548	  }
549	
550	  if (req.method === 'POST' && url === '/goto') {
551	    const { x, y, z } = body;
552	    if ([x, y, z].some((v) => typeof v !== 'number' || !Number.isFinite(v))) {
553	      return reply(res, 400, { error: 'need numeric x,y,z' });
554	    }
555	    if (inNoGo(x, z)) return reply(res, 403, { error: 'target inside FEL no-go zone', nogo: NOGO });
556	    sendChat(`#goto ${x} ${y} ${z}`);
557	    state.task = { kind: 'goto', x, y, z, at: Date.now() };
558	    state.aborted = null;
559	    return reply(res, 200, { ok: true, sent: `#goto ${x} ${y} ${z}` });
560	  }
561	
562	  if (req.method === 'POST' && url === '/mine') {
563	    const { block, count } = body;
564	    if (!block) return reply(res, 400, { error: 'need block' });
565	    sendChat(`#mine ${count ?? ''} ${block}`.replace(/\s+/g, ' ').trim());
566	    state.task = { kind: 'mine', block, count, at: Date.now() };
567	    return reply(res, 200, { ok: true });
568	  }
569	
570	  if (req.method === 'POST' && url === '/tunnel') {
571	    const { h, w, d } = body;
572	    // Projected end of a tunnel is unknown without a heading; gate on the
573	    // CURRENT position instead — refuse to start a break-capable job from
574	    // inside the FEL box at all.
575	    if (state.position && inNoGo(state.position.x, state.position.z)) {
576	      return reply(res, 403, { error: 'current position inside FEL no-go zone; refusing to tunnel' });
577	    }
578	    sendChat(`#tunnel ${h ?? ''} ${w ?? ''} ${d ?? ''}`.replace(/\s+/g, ' ').trim());
579	    state.task = { kind: 'tunnel', h, w, d, at: Date.now() };
580	    return reply(res, 200, { ok: true });
581	  }
582	
583	  if (req.method === 'POST' && url === '/farm') {
584	    sendChat(`#farm ${body.range ?? ''}`.trim());
585	    state.task = { kind: 'farm', at: Date.now() };
586	    return reply(res, 200, { ok: true });
587	  }
588	
589	  if (req.method === 'POST' && url === '/follow') {
590	    if (!body.player) return reply(res, 400, { error: 'need player' });
591	    sendChat(`#follow ${body.player}`);
592	    state.task = { kind: 'follow', player: body.player, at: Date.now() };
593	    return reply(res, 200, { ok: true });
594	  }
595	
596	  if (req.method === 'POST' && url === '/stop') {
597	    sendChat('#stop');
598	    state.task = null;
599	    return reply(res, 200, { ok: true });
600	  }
601	
602	  // Whitelisted read-only baritone words (client-side only, never server chat).
603	  if (req.method === 'POST' && url === '/console') {
604	    const cmd = String(body.cmd || '').trim();
605	    if (!SAFE_CONSOLE_CHAT.has(cmd)) return reply(res, 403, { error: 'command not whitelisted', allowed: [...SAFE_CONSOLE_CHAT] });
606	    if (cmd === '#goal') posPollPending = true;
607	    sendChat(cmd);
608	    return reply(res, 200, { ok: true, sent: cmd });
609	  }
610	
611	  if (req.method === 'POST' && url === '/disconnect') {
612	    try { sendChat('#stop'); } catch {}
613	    setTimeout(() => { try { sendConsole('disconnect'); } catch {} }, 500);
614	    state.task = null;
615	    state.connected = false;
616	    state.phase = 'disconnected';
617	    if (posPollTimer) clearInterval(posPollTimer);
618	    return reply(res, 200, { ok: true });
619	  }
620	
621	  if (req.method === 'POST' && url === '/relog') {
622	    try {
623	      sendConsole('disconnect');
624	      setTimeout(() => sendConsole(`connect ${MC_HOST} ${MC_PORT}`), 3000);
625	      return reply(res, 200, { ok: true, mode: 'soft' });
626	    } catch {
627	      killTree(() => boot());
628	      return reply(res, 200, { ok: true, mode: 'full-relaunch' });
629	    }
630	  }
631	
632	  if (req.method === 'POST' && url === '/shutdown') {
633	    reply(res, 200, { ok: true, shuttingDown: true });
634	    state.phase = 'shutting-down';
635	    if (posPollTimer) clearInterval(posPollTimer);
636	    try { sendChat('#stop'); } catch {}
637	    setTimeout(() => { try { sendConsole('disconnect'); } catch {} }, 500);
638	    setTimeout(() => killTree(() => process.exit(0)), 3500);
639	    return;
640	  }
641	
642	  return reply(res, 404, { error: 'not found' });
643	}
644	
645	const server = http.createServer((req, res) => {
646	  let raw = '';
647	  req.on('data', (c) => (raw += c));
648	  req.on('end', () => {
649	    let json = {};
650	    try { json = raw ? JSON.parse(raw) : {}; } catch {}
651	    try { route(req, res, json); }
652	    catch (e) { reply(res, 500, { error: String(e.message || e) }); }
653	  });
