#!/usr/bin/env node
// =============================================================================
// baritone-runner.mjs — HTTP wrapper around a HeadlessMc + Baritone MC client.
//
// One node process per bot. Command wire = HMC launcher stdin.
// State wire  = the game client's own <gameDir>/logs/latest.log tail.
// NO RCON anywhere in this file. LAW.
//
// Launch recipe below is the FIELD-PROVEN one from cave/BARITONE.md
// ("Round 2 FINAL update — verdict: WORKS", 2026-09-01) as first proven by
// hmc-launch8.mjs. Do not "improve" the three load-bearing quirks:
//   1. NO  -lwjgl               -> the headless render stub hangs forever on
//                                  1.21.11 blur-pipeline uniforms. Real GPU +
//                                  hidden real window instead.
//   2. NO  --quickPlayMultiplayer -> silently never fires on this HMC/MC pair.
//                                  Join is driven manually by writing
//                                  `connect <host> <port>` to launcher stdin
//                                  once the title screen is up (~35 s).
//   3. YES -Dhmc.jline.enabled=false -> hmc-specifics spins a SECOND JLine
//                                  reader inside Minecraft.<init>; over a
//                                  plain (non-TTY) pipe it throws
//                                  IllegalStateException and kills the client.
//                                  The softer hmc.jline.dumb.* flags do NOT
//                                  fix this one.
// =============================================================================
//
// -----------------------------------------------------------------------------
// PINNED VERSIONS  — every artifact below is an explicit, on-disk, pinned file.
//                    NOTHING in this runner resolves a "latest" URL or tag.
//                    The runner never downloads: preflight() fails loudly if a
//                    pinned file is missing rather than fetching a replacement.
// -----------------------------------------------------------------------------
//   Java runtime      : 21.0.10   C:\Program Files\Java\jdk-21.0.10\bin\java.exe
//   HeadlessMc launcher: 2.10.0   bots/<NAME>/headlessmc-launcher.jar
//                                 (sha-identical copy of
//                                  shared/headlessmc-launcher.jar)
//   Minecraft         : 1.21.11
//   Fabric loader     : 0.19.3    version id `fabric-loader-0.19.3-1.21.11`
//                                 installed under the SHARED mc install
//                                 (%APPDATA%\.minecraft\versions\...)
//   Fabric API mod    : 0.141.6+1.21.11
//                                 fabric-api-0.141.6+1.21.11.jar
//   Baritone          : 1.17.0    baritone-standalone-fabric-1.17.0.jar
//                                 (cabaletta official, built FOR 1.21.11)
//   hmc-specifics     : 2.4.0     hmc-specifics-1.21.11-2.4.0-fabric-release.jar
//                                 (the version-stamped file HMC itself cached
//                                  under HeadlessMC/specifics/ — NOT the
//                                  "-latest" named download in shared/, which
//                                  would double-load as a second copy of the
//                                  same mod and crash fabric)
//
//   HMC_LAUNCH_TARGET below is the launcher's version selector. It is matched
//   against the installed version id `fabric-loader-0.19.3-1.21.11`, which is
//   the only fabric version installed — so it is unambiguous, not a "latest".
// -----------------------------------------------------------------------------
//
// -----------------------------------------------------------------------------
// PER-INSTANCE gameDir — how two bots are kept from colliding
// -----------------------------------------------------------------------------
// HeadlessMc 2.10.0 ignores the launcher process cwd when choosing the game
// directory: by default it passes `--gameDir %APPDATA%\.minecraft` to every
// client it spawns. Two bots would then share one logs/latest.log (the state
// wire), one baritone/settings.txt, one options.txt, one servers.dat.
//
// Mechanism found (by decompiling headlessmc-launcher-2.10.0.jar):
//   LauncherProperties.GAME_DIR = config key `hmc.gamedir`
//     -> LauncherBuilder reads it, defaulting to the mc install dir, and
//        FileManager.mkdir()s it
//     -> ProcessFactory passes it to the child JVM as `--gameDir <path>`
//        and logs `Game will run in <path>` (our proof line).
//   Sibling key `hmc.game.dir.for.each.version` would append a per-version
//   subdir; pinned to false so the path is exactly what we set.
//
// It is a CONFIG-FILE key, not a `launch` flag (the launch command has no
// gamedir flag), and HMC's config.properties is resolved from the launcher's
// cwd — which IS per bot. So the isolation is:
//
//   bots/<NAME>/                        <- launcher cwd, per bot
//     headlessmc-launcher.jar
//     HeadlessMC/config.properties      <- carries hmc.gamedir + offline user
//     HeadlessMC/<uuid>/                <- per-bot extracted natives (already
//                                          isolated by cwd, HMC-side)
//     gamedir/                          <- hmc.gamedir target, per bot
//       mods/                           <- pinned mods, per bot
//       logs/latest.log                 <- STATE WIRE, per bot
//       baritone/settings.txt           <- safety config, per bot
//       options.txt, servers.dat, saves/, screenshots/ ...
//
// Shared (read-mostly, safe to share, big): the mc install at
// %APPDATA%\.minecraft — versions/, libraries/, assets/. Those are content-
// addressed downloads, not per-session state, so sharing them costs nothing
// and saves ~1 GB per extra bot.
//
// writeHmcConfig() rewrites config.properties on every boot, so hmc.gamedir
// can never drift back to the shared profile.
// -----------------------------------------------------------------------------

import { spawn, execFile } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import http from 'node:http';

// ---------------------------------------------------------------- args -------
function arg(name, def) {
  const i = process.argv.indexOf(`--${name}`);
  return i !== -1 ? process.argv[i + 1] : def;
}
const flag = (name) => process.argv.includes(`--${name}`);

const NAME = arg('name', 'BariBrute');
const PORT = Number(arg('port', 3301));
const MC_HOST = arg('host', 'localhost');
const MC_PORT = arg('mcport', '25565');
const SHOW_WINDOW = flag('show-window'); // default: hide the real GLFW window

if (NAME.length > 16) {
  console.error(`FATAL: bot name "${NAME}" is ${NAME.length} chars; MC caps usernames at 16.`);
  process.exit(1);
}

// ------------------------------------------------------- pinned paths --------
const ROOT = 'C:\\Users\\phili\\tools\\baritone-lifter';
const SHARED = path.join(ROOT, 'shared');
const BOT_DIR = path.join(ROOT, 'bots', NAME);
const HMC_DIR = path.join(BOT_DIR, 'HeadlessMC');
const HMC_CONFIG = path.join(HMC_DIR, 'config.properties');
const GAME_DIR = path.join(BOT_DIR, 'gamedir'); // <- per-instance, see header
const MODS_DIR = path.join(GAME_DIR, 'mods');
const LOG_PATH = path.join(GAME_DIR, 'logs', 'latest.log');
const SETTINGS_PATH = path.join(GAME_DIR, 'baritone', 'settings.txt');

const JAVA = 'C:\\Program Files\\Java\\jdk-21.0.10\\bin\\java.exe';
const LAUNCHER_JAR = 'headlessmc-launcher.jar'; // HMC 2.10.0, resolved in BOT_DIR
const MC_INSTALL = path.join(process.env.APPDATA || 'C:\\Users\\phili\\AppData\\Roaming', '.minecraft');

const HMC_LAUNCH_TARGET = 'fabric:1.21.11'; // -> fabric-loader-0.19.3-1.21.11
const JVM_ARGS = '-Xmx3G -XX:+UseG1GC -Dhmc.jline.enabled=false';

// Pinned mods, copied into the per-instance MODS_DIR at preflight if absent.
// dest name is authoritative — a differently-named copy of the same mod makes
// fabric abort with a duplicate-mod error.
const PINNED_MODS = [
  {
    name: 'fabric-api-0.141.6+1.21.11.jar',
    sources: [
      path.join(SHARED, 'fabric-api-0.141.6+1.21.11.jar'),
      path.join(MC_INSTALL, 'mods', 'fabric-api-0.141.6+1.21.11.jar'),
    ],
  },
  {
    name: 'baritone-standalone-fabric-1.17.0.jar',
    sources: [path.join(SHARED, 'baritone-standalone-fabric-1.17.0.jar')],
  },
  {
    name: 'hmc-specifics-1.21.11-2.4.0-fabric-release.jar',
    sources: [
      path.join(HMC_DIR, 'specifics', 'hmc-specifics', 'hmc-specifics-1.21.11-2.4.0-fabric-release.jar'),
      path.join(SHARED, 'hmc-specifics-1.21.11-2.4.0-fabric-release.jar'),
    ],
  },
];

// ----------------------------------------------------------- timings --------
const LAUNCH_DELAY_MS = 4000;   // launcher boot -> accepts console words
const CONNECT_DELAY_MS = 35000; // launch -> title screen up (proven ~35 s)
const CHATDEBUG_DELAY_MS = 12000; // after connect, before pushing #set chatDebug

// ------------------------------------------------------- FEL no-go ----------
const NOGO = { x: -3, z: 4, r: 15, pad: 5 }; // padded box: x [-23,17], z [-16,24], all y
function inNoGo(x, z) {
  return x >= NOGO.x - NOGO.r - NOGO.pad && x <= NOGO.x + NOGO.r + NOGO.pad
      && z >= NOGO.z - NOGO.r - NOGO.pad && z <= NOGO.z + NOGO.r + NOGO.pad;
}

// --------------------------------------------------------------- state ------
const state = {
  name: NAME,
  connected: false,
  position: null,
  positionSource: null,
  task: null,
  lastBaritoneLine: null,
  bootedAt: Date.now(),
  joinedAt: null,
  aborted: null,
  gameDir: GAME_DIR,
  phase: 'starting',
};

const chatLog = [];       // recent [CHAT] lines, for /log
const CHAT_LOG_MAX = 400;

let child = null;
let logOffset = 0;
let logWatchTimer = null;
let posPollTimer = null;
let posPollPending = false;
let preexistingJavaPids = new Set();

function log(line) {
  process.stdout.write(`[${new Date().toISOString()}] [${NAME}] ${line}\n`);
}

// -------------------------------------------------------------- console -----
function sendConsole(cmd) {
  if (!child || !child.stdin || child.stdin.destroyed) throw new Error('launcher not running');
  log(`SEND: ${cmd}`);
  child.stdin.write(cmd + '\n');
}

// A `#`-prefixed chat line is intercepted CLIENT-SIDE by Baritone before it
// leaves for the server, so this never produces real server chat.
function sendChat(msg) {
  // hmc-specifics rejects `msg` before the client is in a world
  // ("You need to be ingame to send a message!"), so don't bother.
  if (!state.connected) throw new Error('not in world');
  sendConsole(`msg ${msg}`);
}

// --------------------------------------------------------- preflight --------
function readProps(file) {
  const out = new Map();
  if (!fs.existsSync(file)) return out;
  for (const raw of fs.readFileSync(file, 'utf8').split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith('#') || line.startsWith('!')) continue;
    const i = line.indexOf('=');
    if (i === -1) continue;
    out.set(line.slice(0, i).trim(), line.slice(i + 1));
  }
  return out;
}

function writeHmcConfig() {
  fs.mkdirSync(HMC_DIR, { recursive: true });
  const props = readProps(HMC_CONFIG);
  // Forward slashes: java.util.Properties treats "\" as an escape character.
  props.set('hmc.gamedir', GAME_DIR.replace(/\\/g, '/'));
  props.set('hmc.game.dir.for.each.version', 'false');
  props.set('hmc.offline.username', NAME);
  // Launcher-side JLine: harmless, keeps the launcher console sane over a pipe.
  // (The load-bearing one is -Dhmc.jline.enabled=false on the CHILD jvm, in
  // JVM_ARGS above — config.properties does not reach the child.)
  props.set('hmc.jline.dumb.when.no.console', 'true');
  if (!props.has('hmc.java.versions')) props.set('hmc.java.versions', JAVA.replace(/\\/g, '/'));
  const body = [...props.entries()].map(([k, v]) => `${k}=${v}`).join('\n') + '\n';
  fs.writeFileSync(HMC_CONFIG, body);
  log(`hmc.gamedir=${props.get('hmc.gamedir')}`);
}

function preflight() {
  const missing = [];
  if (!fs.existsSync(JAVA)) missing.push(`java: ${JAVA}`);
  if (!fs.existsSync(path.join(BOT_DIR, LAUNCHER_JAR))) missing.push(`launcher: ${path.join(BOT_DIR, LAUNCHER_JAR)}`);
  if (!fs.existsSync(path.join(MC_INSTALL, 'versions', 'fabric-loader-0.19.3-1.21.11'))) {
    missing.push(`fabric version: ${path.join(MC_INSTALL, 'versions', 'fabric-loader-0.19.3-1.21.11')}`);
  }

  fs.mkdirSync(MODS_DIR, { recursive: true });
  for (const mod of PINNED_MODS) {
    const dest = path.join(MODS_DIR, mod.name);
    if (fs.existsSync(dest)) continue;
    const src = mod.sources.find((s) => fs.existsSync(s));
    if (!src) { missing.push(`mod (no pinned source on disk): ${mod.name}`); continue; }
    fs.copyFileSync(src, dest);
    log(`installed pinned mod ${mod.name} <- ${src}`);
  }

  // Any mod in the per-instance mods dir that is not on the pinned list is a
  // version-drift hazard (e.g. an auto-installed "-latest" specifics jar
  // sitting next to the pinned one). Refuse to boot rather than guess.
  const pinnedNames = new Set(PINNED_MODS.map((m) => m.name));
  for (const f of fs.readdirSync(MODS_DIR)) {
    if (f.endsWith('.jar') && !pinnedNames.has(f)) missing.push(`UNPINNED mod present: ${path.join(MODS_DIR, f)}`);
  }

  if (missing.length) {
    console.error('FATAL preflight — pinned artifacts missing/unexpected (this runner never downloads):');
    for (const m of missing) console.error('  - ' + m);
    process.exit(1);
  }
  log(`preflight ok — mods: ${[...pinnedNames].join(', ')}`);
}

function writeBaritoneSettings() {
  fs.mkdirSync(path.dirname(SETTINGS_PATH), { recursive: true });
  fs.writeFileSync(SETTINGS_PATH, [
    // CHIEF RULING 2026-09-01: legitMine OFF — parity with the mineflayer
    // fleet's own /mine, which already finds buried ore via chunk-data scans.
    // Visible-only was holding Baritone to a stricter standard than the rest
    // of the fleet, not a stricter no-cheat law. See cave/BARITONE.md 5a.
    'legitMine false',
    'allowDownward false',
    'minYLevelWhileMining -54',
    'maxYLevelWhileMining 95',
    // FIELD-VERIFIED 1.17.0 format: bare comma-separated block ids, NO square
    // brackets. The bracketed form from the blueprint makes baritone log
    // "Unable to parse line ... Invalid block name [chest" and drop the whole
    // setting, silently losing the protection.
    'blocksToDisallowBreaking chest,trapped_chest,crafting_table,furnace,blast_furnace,oak_sign,oak_wall_sign,barrel',
    'chatDebug true',
    '',
  ].join('\n'));
}

// ------------------------------------------------------------- window -------
// Hide the real GLFW window. We do NOT run -lwjgl (see header), so a real
// window exists; fleet law is no visible client. Identify it as "a java
// process that did not exist before we spawned the launcher" — never touch the
// server JVM or any other pre-existing java process.
function snapshotJavaPids() {
  return new Promise((resolve) => {
    execFile('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command',
      "Get-Process java,javaw -ErrorAction SilentlyContinue | ForEach-Object { $_.Id }"],
      (err, stdout) => {
        const pids = new Set(String(stdout || '').split(/\r?\n/).map((s) => s.trim()).filter(Boolean));
        resolve(pids);
      });
  });
}

function hideGameWindow() {
  if (SHOW_WINDOW) return;
  const skip = [...preexistingJavaPids, String(child?.pid ?? 0)].join(',');
  const ps = `
$skip = @(${skip.split(',').filter(Boolean).map((p) => p).join(',') || '0'})
Add-Type @"
using System;
using System.Runtime.InteropServices;
public class Win32HideBari {
  [DllImport("user32.dll")] public static extern bool ShowWindowAsync(IntPtr hWnd, int nCmdShow);
}
"@
Get-Process java,javaw -ErrorAction SilentlyContinue | Where-Object { $skip -notcontains $_.Id -and $_.MainWindowHandle -ne 0 } | ForEach-Object {
  [Win32HideBari]::ShowWindowAsync($_.MainWindowHandle, 0) | Out-Null
  "hid pid=$($_.Id)"
}`;
  execFile('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', ps], (err, stdout) => {
    if (stdout && stdout.trim()) log(`WINDOW: ${stdout.trim()}`);
  });
}

// --------------------------------------------------------------- boot -------
async function boot() {
  fs.mkdirSync(BOT_DIR, { recursive: true });
  fs.mkdirSync(GAME_DIR, { recursive: true });
  writeHmcConfig();
  preflight();
  writeBaritoneSettings();

  // Fresh state wire: drop the previous session's latest.log so the tail can
  // start at offset 0 with no risk of replaying stale [CHAT] lines.
  try { if (fs.existsSync(LOG_PATH)) fs.unlinkSync(LOG_PATH); } catch { /* held open, tail handles it */ }

  preexistingJavaPids = await snapshotJavaPids();
  log(`pre-existing java pids (never touched): ${[...preexistingJavaPids].join(',') || 'none'}`);

  child = spawn(JAVA, ['-jar', LAUNCHER_JAR], {
    cwd: BOT_DIR,
    stdio: ['pipe', 'pipe', 'pipe'],
    windowsHide: true,
  });
  log(`launcher pid=${child.pid}`);
  try { fs.mkdirSync(path.join(ROOT, 'pids'), { recursive: true }); fs.writeFileSync(path.join(ROOT, 'pids', `${NAME}.pid`), String(child.pid)); } catch {}

  child.stdout.on('data', (d) => handleLauncherOut(String(d)));
  child.stderr.on('data', (d) => process.stderr.write(`[hmc-err] ${d}`));
  child.on('exit', (code, sig) => {
    log(`launcher exited code=${code} sig=${sig}`);
    state.connected = false;
    state.phase = 'dead';
    child = null;
  });

  startLogTail();

  const hideTimer = setInterval(hideGameWindow, 3000);
  setTimeout(() => clearInterval(hideTimer), 5 * 60 * 1000);

  setTimeout(() => {
    state.phase = 'launching';
    // PROVEN LINE: no -lwjgl, no --quickPlayMultiplayer, jline off on the child.
    sendConsole(`launch ${HMC_LAUNCH_TARGET} -offline --jvm "${JVM_ARGS}"`);

    setTimeout(() => {
      state.phase = 'connecting';
      // hmc-specifics ConnectCommand: raw line `connect <host> [port]`
      // (args[1]=host, args[2]=port; verified by javap on ConnectCommand.class)
      sendConsole(`connect ${MC_HOST} ${MC_PORT}`);
      setTimeout(() => {
        try { sendChat('#set chatDebug true'); } catch {}
        startPosPoll();
      }, CHATDEBUG_DELAY_MS);
    }, CONNECT_DELAY_MS);
  }, LAUNCH_DELAY_MS);
}

function handleLauncherOut(text) {
  process.stdout.write(`[hmc] ${text}`);
  // The launcher relays the game's stdout, so baritone's own path chatter
  // ("Path goes for N blocks") shows up here too.
  for (const line of text.split(/\r?\n/)) {
    if (!line.trim()) continue;
    if (/Path goes for|Baritone|\[B\]/i.test(line)) state.lastBaritoneLine = line.trim();
  }
}

// ------------------------------------------------------------ log tail ------
function startLogTail() {
  if (logWatchTimer) clearInterval(logWatchTimer);
  logOffset = 0;
  let lastSize = -1;
  logWatchTimer = setInterval(() => {
    try {
      const stat = fs.statSync(LOG_PATH);
      if (stat.size < lastSize) logOffset = 0; // rotated (relog) -> reopen from start
      lastSize = stat.size;
      if (stat.size > logOffset) {
        const fd = fs.openSync(LOG_PATH, 'r');
        const buf = Buffer.alloc(stat.size - logOffset);
        fs.readSync(fd, buf, 0, buf.length, logOffset);
        fs.closeSync(fd);
        logOffset = stat.size;
        for (const raw of buf.toString('utf8').split('\n')) {
          // latest.log is CRLF and the vanilla chat logger embeds ANSI SGR
          // colour codes INSIDE the "[Baritone]" tag, e.g.
          //   [CHAT] \e[m\e[38;5;5m[\e[38;5;13mBaritone\e[38;5;5m]\e[0m ...
          // Both must go before any regex, or "[Baritone]" never matches and
          // a trailing \r defeats every $-anchored pattern.
          const line = raw.replace(/\x1b\[[0-9;]*[A-Za-z]/g, '').replace(/\r/g, '');
          if (line.trim()) handleLogLine(line);
        }
      }
    } catch { /* not created yet */ }
  }, 500);
}

const CHAT_RE = /\[CHAT\]\s*(.*)$/;
const CHAT_BARITONE_RE = /\[CHAT\].*?\[(?:Baritone|B)\]\s*(.+)/;
// Baritone GoalBlock toString, e.g. "GoalBlock{x=11,y=94,z=48}"
const GOALBLOCK_RE = /GoalBlock\{x=(-?\d+),\s*y=(-?\d+),\s*z=(-?\d+)\}/;
// BetterBlockPos / generic "(x, y, z)" triple from chatDebug path lines
const POS_RE = /\((-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?)\)/;
// NOT plain "[CHAT]" — baritone prints settings-parse chatter to the local HUD
// while still on the title screen, which false-positives the join.
const JOIN_RE = /Connecting to |logged in with entity id|\[System\] \[CHAT\]/i;

function setPosition(x, y, z, source) {
  state.position = { x, y, z };
  state.positionSource = source;
  if (inNoGo(x, z)) {
    // Layer 2 watchdog. Baritone has no native keep-out zone, so a legal goto
    // can still path THROUGH the FEL box.
    log(`WATCHDOG: position ${x},${y},${z} inside FEL no-go box -- STOP`);
    try { sendChat('#stop'); } catch {}
    state.aborted = 'nogo';
    state.task = null;
  }
}

function handleLogLine(line) {
  if (!state.connected && JOIN_RE.test(line)) {
    state.connected = true;
    state.phase = 'in-world';
    state.joinedAt = Date.now();
    log('JOIN detected');
  }
  const c = line.match(CHAT_RE);
  if (c) {
    chatLog.push(c[1].trim());
    if (chatLog.length > CHAT_LOG_MAX) chatLog.shift();
  }
  const m = line.match(CHAT_BARITONE_RE);
  if (!m) return;
  state.lastBaritoneLine = m[1].trim();

  const g = m[1].match(GOALBLOCK_RE);
  if (g && posPollPending) {
    posPollPending = false;
    setPosition(parseInt(g[1], 10), parseInt(g[2], 10), parseInt(g[3], 10), 'goal-poll');
    return;
  }
  const p = m[1].match(POS_RE);
  if (p) setPosition(parseFloat(p[1]), parseFloat(p[2]), parseFloat(p[3]), 'chatDebug');
}

// Position poll. `#goal` with no args sets baritone's goal to the player's
// CURRENT position and echoes it back — a clean position read. It mutates the
// goal, so it is only ever fired while IDLE; during a task the position comes
// from chatDebug path lines instead. Never sends anything to server chat.
function startPosPoll() {
  if (posPollTimer) clearInterval(posPollTimer);
  posPollTimer = setInterval(() => {
    if (!state.connected || state.task || !child) return;
    try { posPollPending = true; sendChat('#goal'); } catch {}
  }, 4000);
}

// ------------------------------------------------------------- shutdown ----
function killTree(cb) {
  const pid = child?.pid;
  const known = new Set(preexistingJavaPids);
  const skip = [...known].join(',') || '0';
  const ps = `
$skip = @(${skip})
Get-Process java,javaw -ErrorAction SilentlyContinue | Where-Object { $skip -notcontains $_.Id } | ForEach-Object {
  "killing pid=$($_.Id)"
  Stop-Process -Id $_.Id -Force -ErrorAction SilentlyContinue
}`;
  try { if (pid) process.kill(pid); } catch {}
  execFile('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', ps], (e, out) => {
    if (out && out.trim()) log(`KILL: ${out.trim()}`);
    cb && cb();
  });
}

// ----------------------------------------------------------------- HTTP -----
function reply(res, code, obj) {
  res.writeHead(code, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(obj));
}

const SAFE_CONSOLE_CHAT = new Set(['#eta', '#proc', '#goal', '#version', '#pause', '#resume']);

function route(req, res, body) {
  const url = req.url.split('?')[0];

  if (req.method === 'GET' && url === '/status') {
    return reply(res, 200, {
      name: NAME,
      position: state.position,
      positionSource: state.positionSource,
      task: state.task,
      lastBaritoneLine: state.lastBaritoneLine,
      connected: state.connected,
      phase: state.phase,
      uptime: Date.now() - state.bootedAt,
      joinedAt: state.joinedAt,
      aborted: state.aborted,
      gameDir: state.gameDir,
      launcherPid: child?.pid ?? null,
    });
  }

  if (req.method === 'GET' && url === '/log') {
    const n = Number(new URL(req.url, 'http://x').searchParams.get('tail') || 40);
    return reply(res, 200, { lines: chatLog.slice(-n) });
  }

  if (req.method === 'POST' && url === '/goto') {
    const { x, y, z } = body;
    if ([x, y, z].some((v) => typeof v !== 'number' || !Number.isFinite(v))) {
      return reply(res, 400, { error: 'need numeric x,y,z' });
    }
    if (inNoGo(x, z)) return reply(res, 403, { error: 'target inside FEL no-go zone', nogo: NOGO });
    sendChat(`#goto ${x} ${y} ${z}`);
    state.task = { kind: 'goto', x, y, z, at: Date.now() };
    state.aborted = null;
    return reply(res, 200, { ok: true, sent: `#goto ${x} ${y} ${z}` });
  }

  if (req.method === 'POST' && url === '/mine') {
    const { block, count } = body;
    if (!block) return reply(res, 400, { error: 'need block' });
    sendChat(`#mine ${count ?? ''} ${block}`.replace(/\s+/g, ' ').trim());
    state.task = { kind: 'mine', block, count, at: Date.now() };
    return reply(res, 200, { ok: true });
  }

  if (req.method === 'POST' && url === '/tunnel') {
    const { h, w, d } = body;
    // Projected end of a tunnel is unknown without a heading; gate on the
    // CURRENT position instead — refuse to start a break-capable job from
    // inside the FEL box at all.
    if (state.position && inNoGo(state.position.x, state.position.z)) {
      return reply(res, 403, { error: 'current position inside FEL no-go zone; refusing to tunnel' });
    }
    sendChat(`#tunnel ${h ?? ''} ${w ?? ''} ${d ?? ''}`.replace(/\s+/g, ' ').trim());
    state.task = { kind: 'tunnel', h, w, d, at: Date.now() };
    return reply(res, 200, { ok: true });
  }

  if (req.method === 'POST' && url === '/farm') {
    sendChat(`#farm ${body.range ?? ''}`.trim());
    state.task = { kind: 'farm', at: Date.now() };
    return reply(res, 200, { ok: true });
  }

  if (req.method === 'POST' && url === '/follow') {
    if (!body.player) return reply(res, 400, { error: 'need player' });
    sendChat(`#follow ${body.player}`);
    state.task = { kind: 'follow', player: body.player, at: Date.now() };
    return reply(res, 200, { ok: true });
  }

  if (req.method === 'POST' && url === '/stop') {
    sendChat('#stop');
    state.task = null;
    return reply(res, 200, { ok: true });
  }

  // Whitelisted read-only baritone words (client-side only, never server chat).
  if (req.method === 'POST' && url === '/console') {
    const cmd = String(body.cmd || '').trim();
    if (!SAFE_CONSOLE_CHAT.has(cmd)) return reply(res, 403, { error: 'command not whitelisted', allowed: [...SAFE_CONSOLE_CHAT] });
    if (cmd === '#goal') posPollPending = true;
    sendChat(cmd);
    return reply(res, 200, { ok: true, sent: cmd });
  }

  if (req.method === 'POST' && url === '/disconnect') {
    try { sendChat('#stop'); } catch {}
    setTimeout(() => { try { sendConsole('disconnect'); } catch {} }, 500);
    state.task = null;
    state.connected = false;
    state.phase = 'disconnected';
    if (posPollTimer) clearInterval(posPollTimer);
    return reply(res, 200, { ok: true });
  }

  if (req.method === 'POST' && url === '/relog') {
    try {
      sendConsole('disconnect');
      setTimeout(() => sendConsole(`connect ${MC_HOST} ${MC_PORT}`), 3000);
      return reply(res, 200, { ok: true, mode: 'soft' });
    } catch {
      killTree(() => boot());
      return reply(res, 200, { ok: true, mode: 'full-relaunch' });
    }
  }

  if (req.method === 'POST' && url === '/shutdown') {
    reply(res, 200, { ok: true, shuttingDown: true });
    state.phase = 'shutting-down';
    if (posPollTimer) clearInterval(posPollTimer);
    try { sendChat('#stop'); } catch {}
    setTimeout(() => { try { sendConsole('disconnect'); } catch {} }, 500);
    setTimeout(() => killTree(() => process.exit(0)), 3500);
    return;
  }

  return reply(res, 404, { error: 'not found' });
}

const server = http.createServer((req, res) => {
  let raw = '';
  req.on('data', (c) => (raw += c));
  req.on('end', () => {
    let json = {};
    try { json = raw ? JSON.parse(raw) : {}; } catch {}
    try { route(req, res, json); }
    catch (e) { reply(res, 500, { error: String(e.message || e) }); }
  });
});

server.listen(PORT, '127.0.0.1', () => log(`HTTP listening on 127.0.0.1:${PORT}`));

boot().catch((e) => { log('FATAL boot: ' + e.stack); process.exit(1); });

for (const sig of ['SIGINT', 'SIGTERM']) {
  process.on(sig, () => killTree(() => process.exit(0)));
}

