const fs = require('fs');
const nbt = require('prismarine-nbt');
const path = require('path');

function decodeVarInts(bytes, count) {
  const out = [];
  let offset = 0;
  for (let i = 0; i < count; i++) {
    let value = 0, size = 0;
    while (true) {
      const b = bytes[offset++];
      value |= (b & 0x7f) << (size * 7);
      size++;
      if ((b & 0x80) === 0) break;
      if (offset > bytes.length) throw new Error('ran off end of buffer decoding varint ' + i);
    }
    out.push(value);
  }
  return { out, bytesConsumed: offset };
}

const dir = 'cave/schematics';
const files = ['sites_classic-village-house.v2.schem', 'sites_cozy-cabin.v2.schem', 'sites_rustic-farmhouse.v2.schem'];

(async () => {
  for (const f of files) {
    const buf = fs.readFileSync(path.join(dir, f));
    const { parsed } = await nbt.parse(buf);
    const v = parsed.value;
    const w = v.Width.value, h = v.Height.value, l = v.Length.value;
    const paletteEntries = Object.entries(v.Palette.value).map(([k, tag]) => [tag.value, k]);
    const paletteSize = paletteEntries.length;
    const blockDataBytes = Buffer.from(v.BlockData.value.map(b => b & 0xff));
    const volume = w*h*l;
    const { out: indices, bytesConsumed } = decodeVarInts(blockDataBytes, volume);
    const badIdx = indices.filter(i => i < 0 || i >= paletteSize);
    const counts = {};
    for (const i of indices) counts[i] = (counts[i]||0)+1;
    const idxToName = Object.fromEntries(paletteEntries);
    const top = Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([i,c])=>idxToName[i]+':'+c);
    console.log(f, ' volume=', volume, ' bytesConsumed=', bytesConsumed, '/', blockDataBytes.length, ' badIndices=', badIdx.length, ' top5=', top.join(', '));
  }
})().catch(e => { console.error('ERR', e.stack); process.exit(1); });
