// ------------------------------------------------------------- shutdown ----
function killTree(cb) {
  const pid = child?.pid;
  const known = new Set(preexistingJavaPids);
  const skip = [...known].join(',') || '0';
  const ps = `
$skip = @(${skip})
Get-Process java,javaw -ErrorAction SilentlyContinue | Where-Object { $skip -notcontains $_.Id } | ForEach-Object {
  "killing pid=$($_.Id)"
  Stop-Process -Id $_.Id -Force -ErrorAction SilentlyContinue
}`;
  try { if (pid) process.kill(pid); } catch {}
  execFile('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', ps], (e, out) => {
    if (out && out.trim()) log(`KILL: ${out.trim()}`);
    cb && cb();
  });
}

