// ------------------------------------------------------------- shutdown ----
// FIELD-CONFIRMED BUG, 2026-09-01: the old killTree() killed every java/javaw
// process EXCEPT whatever was in `preexistingJavaPids` -- a snapshot taken
// once at THIS bot's own boot(). That's only correct in a single-bot world:
// the moment a SECOND bot boots later, its pid was never in the first bot's
// snapshot, so shutting down/relaunching the FIRST bot sweeps up every bot
// that started AFTER it as "collateral". Live-fired: a routine BariBrute-only
// relaunch killed both BariThak and BariOok's JVMs (both booted after
// BariBrute) with zero warning -- confirmed via their latest.log tails
// stopping dead at the exact instant BariBrute's shutdown fired, no crash
// trace, i.e. an external Stop-Process, not a mod/JVM fault.
// Fix: target THIS bot's own process tree directly (launcher pid + its
// direct java/javaw child), not "guess by exclusion". No staleness possible.
function killTree(cb) {
  const pid = child?.pid;
  try { if (pid) process.kill(pid); } catch {}
  if (!pid) { cb && cb(); return; }
  const ps = `
$root = ${pid}
Get-CimInstance Win32_Process -Filter "Name='java.exe' OR Name='javaw.exe'" | Where-Object { $_.ProcessId -eq $root -or $_.ParentProcessId -eq $root } | ForEach-Object {
  "killing pid=$($_.ProcessId)"
  Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue
}`;
  execFile('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', ps], (e, out) => {
    if (out && out.trim()) log(`KILL: ${out.trim()}`);
    cb && cb();
  });
}

