function writeBaritoneSettings() {
  fs.mkdirSync(path.dirname(SETTINGS_PATH), { recursive: true });
  fs.writeFileSync(SETTINGS_PATH, [
    // CHIEF RULING 2026-09-01: legitMine OFF — parity with the mineflayer
    // fleet's own /mine, which already finds buried ore via chunk-data scans.
    // Visible-only was holding Baritone to a stricter standard than the rest
    // of the fleet, not a stricter no-cheat law. See cave/BARITONE.md 5a.
    'legitMine false',
    'allowDownward false',
    'minYLevelWhileMining -54',
    'maxYLevelWhileMining 95',
    // FIELD-VERIFIED 1.17.0 format: bare comma-separated block ids, NO square
    // brackets. The bracketed form from the blueprint makes baritone log
    // "Unable to parse line ... Invalid block name [chest" and drop the whole
    // setting, silently losing the protection.
    'blocksToDisallowBreaking chest,trapped_chest,crafting_table,furnace,blast_furnace,oak_sign,oak_wall_sign,barrel',
    // HOUSE-BUILD RESEARCH 2026-09-01 (field-checked against pinned v1.17.0
    // Settings.java/BuilderProcess.java source): default false means
    // BuilderProcess.searchForPlacables() only looks at the 9 HOTBAR slots
    // for placeable material -- restock protocol #4 (mineflayer bots throw
    // stacks at the builder's feet, auto-pickup) fills the full 36-slot
    // inventory, not the hotbar. Without this ON, #build would silently log
    // "Missing materials" for anything not already hotbar-slotted and stall.
    'allowInventory true',
    'chatDebug true',
    '',
  ].join('\n'));
}

