499	const GOALBLOCK_RE = /GoalBlock\{x=(-?\d+),\s*y=(-?\d+),\s*z=(-?\d+)\}/;
500	// BetterBlockPos / generic "(x, y, z)" triple from chatDebug path lines
501	const POS_RE = /\((-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?)\)/;
502	// NOT plain "[CHAT]" — baritone prints settings-parse chatter to the local HUD
503	// while still on the title screen, which false-positives the join.
504	const JOIN_RE = /Connecting to |logged in with entity id|\[System\] \[CHAT\]/i;
505	
506	function setPosition(x, y, z, source) {
507	  state.position = { x, y, z };
508	  state.positionSource = source;
509	  if (inNoGo(x, z)) {
510	    // Layer 2 watchdog. Baritone has no native keep-out zone, so a legal goto
511	    // can still path THROUGH the FEL box.
512	    log(`WATCHDOG: position ${x},${y},${z} inside FEL no-go box -- STOP`);
513	    try { sendChat('#stop'); } catch {}
514	    state.aborted = 'nogo';
515	    state.task = null;
516	  }
517	}
518	
519	function handleLogLine(line) {
520	  if (!state.connected && JOIN_RE.test(line)) {
521	    state.connected = true;
522	    state.phase = 'in-world';
523	    state.joinedAt = Date.now();
524	    log('JOIN detected');
525	  }
526	  const c = line.match(CHAT_RE);
527	  if (c) {
528	    chatLog.push(c[1].trim());
529	    if (chatLog.length > CHAT_LOG_MAX) chatLog.shift();
530	  }
531	  const m = line.match(CHAT_BARITONE_RE);
532	  if (!m) return;
533	  state.lastBaritoneLine = m[1].trim();
534	
535	  const g = m[1].match(GOALBLOCK_RE);
536	  if (g && posPollPending) {
537	    posPollPending = false;
538	    setPosition(parseInt(g[1], 10), parseInt(g[2], 10), parseInt(g[3], 10), 'goal-poll');
539	    return;
540	  }
541	  const p = m[1].match(POS_RE);
542	  if (p) setPosition(parseFloat(p[1]), parseFloat(p[2]), parseFloat(p[3]), 'chatDebug');
