545	// Position poll. `#goal` with no args sets baritone's goal to the player's
546	// CURRENT position and echoes it back — a clean position read. It mutates the
547	// goal, so it is only ever fired while IDLE; during a task the position comes
548	// from chatDebug path lines instead. Never sends anything to server chat.
549	function startPosPoll() {
550	  if (posPollTimer) clearInterval(posPollTimer);
551	  posPollTimer = setInterval(() => {
552	    if (!state.connected || state.task || !child) return;
