const CHAT_RE = /\[CHAT\]\s*(.*)$/;
const CHAT_BARITONE_RE = /\[CHAT\].*?\[(?:Baritone|B)\]\s*(.+)/;
// Baritone GoalBlock toString, e.g. "GoalBlock{x=11,y=94,z=48}"
const GOALBLOCK_RE = /GoalBlock\{x=(-?\d+),\s*y=(-?\d+),\s*z=(-?\d+)\}/;
// BetterBlockPos / generic "(x, y, z)" triple from chatDebug path lines
const POS_RE = /\((-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?)\)/;
// NOT plain "[CHAT]" — baritone prints settings-parse chatter to the local HUD
// while still on the title screen, which false-positives the join.
const JOIN_RE = /Connecting to |logged in with entity id|\[System\] \[CHAT\]/i;

function setPosition(x, y, z, source) {
  state.position = { x, y, z };
  state.positionSource = source;
  if (inNoGo(x, z)) {
    // Layer 2 watchdog. Baritone has no native keep-out zone, so a legal goto
    // can still path THROUGH the FEL box.
    log(`WATCHDOG: position ${x},${y},${z} inside FEL no-go box -- STOP`);
    try { sendChat('#stop'); } catch {}
    state.aborted = 'nogo';
    state.task = null;
  }
}

function handleLogLine(line) {
  if (!state.connected && JOIN_RE.test(line)) {
    state.connected = true;
    state.phase = 'in-world';
    state.joinedAt = Date.now();
    log('JOIN detected');
  }
  const c = line.match(CHAT_RE);
  if (c) {
    chatLog.push(c[1].trim());
    if (chatLog.length > CHAT_LOG_MAX) chatLog.shift();
  }
  const m = line.match(CHAT_BARITONE_RE);
  if (!m) return;
  state.lastBaritoneLine = m[1].trim();

  const g = m[1].match(GOALBLOCK_RE);
  if (g && posPollPending) {
    posPollPending = false;
    setPosition(parseInt(g[1], 10), parseInt(g[2], 10), parseInt(g[3], 10), 'goal-poll');
    return;
  }
  const p = m[1].match(POS_RE);
  if (p) setPosition(parseFloat(p[1]), parseFloat(p[2]), parseFloat(p[3]), 'chatDebug');
}

// Position poll. `#goal` with no args sets baritone's goal to the player's
// CURRENT position and echoes it back — a clean position read. It mutates the
// goal, so it is only ever fired while IDLE; during a task the position comes
// from chatDebug path lines instead. Never sends anything to server chat.
function startPosPoll() {
  if (posPollTimer) clearInterval(posPollTimer);
  posPollTimer = setInterval(() => {
    if (!state.connected || state.task || !child) return;
    try { posPollPending = true; sendChat('#goal'); } catch {}
  }, 4000);
}

