// Issue #9 (cavecrew-mcp), field-proven 3x today: #mine's composite goal can
// wander far off the intended cluster (visible-only candidates pull it away
// -- baritone has no candidate-filter setting that fixes this, checked all
// the build-related Settings.java fields already pulled for the house
// project, nothing there helps). Worst instance: BariThak's '#mine iron_ore
// count:8' built a composite spanning x20-31/y8-34/z51-72 and dragged the
// bot to y26, ~21 levels below the briefed corridor, before a driver could
// catch it by hand. Same shape as the FEL no-go problem (baritone has no
// native keep-in zone either), so same two-layer answer: /mine and /tunnel
// accept an OPTIONAL {x1,y1,z1,x2,y2,z2} box; the position watchdog (same
// path setPosition() already uses for NOGO) auto-#stops the instant the bot
// leaves it, aborted:'workzone'. Optional and off by default -- a driver
// that doesn't pass `zone` gets today's unbounded behavior, unchanged.
function normalizeZone(x1, y1, z1, x2, y2, z2) {
  return {
    minX: Math.min(x1, x2), maxX: Math.max(x1, x2),
    minY: Math.min(y1, y2), maxY: Math.max(y1, y2),
    minZ: Math.min(z1, z2), maxZ: Math.max(z1, z2),
  };
}
function inZone(zone, x, y, z) {
  return x >= zone.minX && x <= zone.maxX
      && y >= zone.minY && y <= zone.maxY
      && z >= zone.minZ && z <= zone.maxZ;
}
// Throws on a malformed zone (caller turns that into a 400) -- returns null
// for "no zone given", which is the unbounded/legacy behavior.
function parseZoneBody(body) {
  if (body.zone == null) return null;
  const { x1, y1, z1, x2, y2, z2 } = body.zone;
  const vals = [x1, y1, z1, x2, y2, z2];
  if (vals.some((v) => typeof v !== 'number' || !Number.isFinite(v))) {
    throw new Error('zone must be {x1,y1,z1,x2,y2,z2}, all numeric');
  }
  return normalizeZone(x1, y1, z1, x2, y2, z2);
}

