// Isolated simulation of the Issue #9 work-zone watchdog logic, copied
// verbatim from the patched baritone-runner.mjs.

function normalizeZone(x1, y1, z1, x2, y2, z2) {
  return {
    minX: Math.min(x1, x2), maxX: Math.max(x1, x2),
    minY: Math.min(y1, y2), maxY: Math.max(y1, y2),
    minZ: Math.min(z1, z2), maxZ: Math.max(z1, z2),
  };
}
function inZone(zone, x, y, z) {
  return x >= zone.minX && x <= zone.maxX
      && y >= zone.minY && y <= zone.maxY
      && z >= zone.minZ && z <= zone.maxZ;
}
function parseZoneBody(body) {
  if (body.zone == null) return null;
  const { x1, y1, z1, x2, y2, z2 } = body.zone;
  const vals = [x1, y1, z1, x2, y2, z2];
  if (vals.some((v) => typeof v !== 'number' || !Number.isFinite(v))) {
    throw new Error('zone must be {x1,y1,z1,x2,y2,z2}, all numeric');
  }
  return normalizeZone(x1, y1, z1, x2, y2, z2);
}

const NOGO = { x: -3, z: 4, r: 15, pad: 5 };
function inNoGo(x, z) {
  return x >= NOGO.x - NOGO.r - NOGO.pad && x <= NOGO.x + NOGO.r + NOGO.pad
      && z >= NOGO.z - NOGO.r - NOGO.pad && z <= NOGO.z + NOGO.r + NOGO.pad;
}

let state, sentStop;
function sendChat(m) { if (m === '#stop') sentStop = true; }
function setPosition(x, y, z, source) {
  state.position = { x, y, z };
  state.positionSource = source;
  if (inNoGo(x, z)) {
    sendChat('#stop');
    state.aborted = 'nogo';
    state.task = null;
    state.workZone = null;
    return;
  }
  if (state.workZone && !inZone(state.workZone, x, y, z)) {
    sendChat('#stop');
    state.aborted = 'workzone';
    state.task = null;
    state.workZone = null;
  }
}

function reset() { state = { position: null, aborted: null, task: { kind: 'mine' }, workZone: null }; sentStop = false; }

// --- 1. real BariThak incident shape: composite x20-31/y8-34/z51-72, corridor y47-49 ---
reset();
try { state.workZone = parseZoneBody({ zone: { x1: 20, y1: 47, z1: 51, x2: 31, y2: 49, z2: 72 } }); } catch (e) { console.log('setup fail', e); }
setPosition(23, 30, 52, 'chatDebug'); // the actual y26-ish drift the driver caught
console.log('1. real incident shape -> aborted:', state.aborted, 'stopSent:', sentStop, state.aborted === 'workzone' && sentStop ? 'PASS' : 'FAIL');

// --- 2. inside zone, no trip ---
reset();
state.workZone = parseZoneBody({ zone: { x1: 20, y1: 47, z1: 51, x2: 31, y2: 49, z2: 72 } });
setPosition(25, 48, 60, 'chatDebug');
console.log('2. inside zone -> aborted:', state.aborted, 'stopSent:', sentStop, state.aborted === null && !sentStop ? 'PASS' : 'FAIL');

// --- 3. no zone given (legacy unbounded) -> never trips no matter where ---
reset();
state.workZone = parseZoneBody({});
setPosition(9999, -50, -9999, 'chatDebug');
console.log('3. no zone -> aborted:', state.aborted, state.aborted === null ? 'PASS' : 'FAIL');

// --- 4. reversed corner order (x2<x1 etc) still normalizes correctly ---
reset();
state.workZone = parseZoneBody({ zone: { x1: 31, y1: 49, z1: 72, x2: 20, y2: 47, z2: 51 } });
setPosition(25, 48, 60, 'chatDebug');
console.log('4. reversed corners, inside -> aborted:', state.aborted, state.aborted === null ? 'PASS' : 'FAIL');
setPosition(25, 30, 60, 'chatDebug');
console.log('4b. reversed corners, outside (y30) -> aborted:', state.aborted, state.aborted === 'workzone' ? 'PASS' : 'FAIL');

// --- 5. malformed zone body throws (400 path) ---
try {
  parseZoneBody({ zone: { x1: 1, y1: 2, z1: 3, x2: 'nope', y2: 5, z2: 6 } });
  console.log('5. malformed zone -> FAIL (did not throw)');
} catch (e) {
  console.log('5. malformed zone -> threw as expected: PASS -', e.message);
}

// --- 6. NOGO still takes precedence / fires independent of workZone ---
reset();
state.workZone = parseZoneBody({ zone: { x1: -100, y1: 0, z1: -100, x2: 100, y2: 200, z2: 100 } }); // huge zone, would NOT trip
setPosition(-3, 100, 4, 'chatDebug'); // dead center of FEL no-go
console.log('6. inside huge workzone but inside NOGO -> aborted:', state.aborted, state.aborted === 'nogo' ? 'PASS' : 'FAIL');

// --- 7. watchdog self-clears workZone after tripping (no repeat-trigger spam) ---
reset();
state.workZone = parseZoneBody({ zone: { x1: 20, y1: 47, z1: 51, x2: 31, y2: 49, z2: 72 } });
setPosition(25, 30, 60, 'chatDebug'); // trips once
sentStop = false;
setPosition(25, 29, 61, 'chatDebug'); // still "outside" but workZone is now null -> should NOT re-trip
console.log('7. no repeat-trigger after first trip -> aborted:', state.aborted, 'stopSentAgain:', sentStop, (state.aborted === 'workzone' && !sentStop) ? 'PASS' : 'FAIL');
EOF
