// /toss prep, 2026-09-01: hmc-specifics' OWN native commands (key/menu/
// gui/click/close -- real classes in the pinned hmc-specifics-2.4.0 jar,
// e.g. KeyCommand.java can press any keyboard key incl. Q/Ctrl+Q for the
// vanilla drop keybind, digits for hotbar select) go over the RAW launcher
// stdin channel via sendConsole(), unprefixed -- NOT baritone's `msg`-
// prefixed chat interception that /console above uses, so they need their
// own whitelist gate rather than reusing SAFE_CONSOLE_CHAT's exact-match.
// Scoped tight to prefixes actually needed for inventory-drop work; still
// experimental (nailing the real click/key sequence live), hence a
// separate, narrower endpoint rather than folding into /console.
const SAFE_NATIVE_PREFIXES = ['key ', 'menu', 'gui', 'click ', 'close'];
if (req.method === 'POST' && url === '/native') {
  const cmd = String(body.cmd || '').trim();
  const allowed = SAFE_NATIVE_PREFIXES.some((p) => cmd === p.trim() || cmd.startsWith(p));
  if (!allowed) return reply(res, 403, { error: 'native command not whitelisted', allowedPrefixes: SAFE_NATIVE_PREFIXES });
  try {
    sendConsole(cmd);
  } catch (e) {
    return reply(res, 500, { error: e.message });
  }
  return reply(res, 200, { ok: true, sent: cmd });
}

