const blockData = Buffer.alloc(volume, 0); // all index 0 = cobblestone (single-byte varint for small index)

const root = {
  type: 'compound',
  name: '',
  value: {
    Version: { type: 'int', value: 2 },
    Width: { type: 'short', value: width },
    Height: { type: 'short', value: height },
    Length: { type: 'short', value: length },
