      'minecraft:cobblestone': { type: 'int', value: 0 },
    }},
    BlockData: { type: 'byteArray', value: [...blockData] },
  },
};

const raw = nbt.writeUncompressed(root, 'big');
const gz = zlib.gzipSync(raw);
fs.writeFileSync('cave/schematics/test_pad_3x3.schem', gz);
console.log('wrote test_pad_3x3.schem,', gz.length, 'bytes');

// round-trip verify
