// Isolated simulation of runToss()'s control flow, copied verbatim
// (with fast/no-op sleep + a mock sendConsole) to verify: correct slot
// sequence, busy-guard/cancellation via /stop mid-run, and that ctrl never
// gets left "stuck held" on an error or cancel.

function sleep(ms) { return new Promise((resolve) => setTimeout(resolve, 0)); } // fast for test

const TOSS_HOTBAR_SLOTS = 9;
let state, calls, throwOnCall;

function sendConsole(cmd) {
  calls.push(cmd);
  if (throwOnCall && calls.length === throwOnCall) throw new Error('simulated failure');
}
function log(l) { calls.push('LOG:' + l); }

async function runToss() {
  for (let slot = 1; slot <= TOSS_HOTBAR_SLOTS; slot++) {
    if (state.task?.kind !== 'toss') return;
    state.task = { kind: 'toss', slot, totalSlots: TOSS_HOTBAR_SLOTS, at: Date.now() };
    try {
      sendConsole(`key ${slot}`);
      await sleep(300);
      sendConsole('key left.control -indefinite');
      await sleep(1500);
      sendConsole('key q');
      sendConsole('key left.control -release');
    } catch (e) {
      log(`toss: aborted on hotbar slot ${slot}: ${e.message}`);
      try { sendConsole('key left.control -release'); } catch {}
      break;
    }
    await sleep(500);
  }
  if (state.task?.kind === 'toss') state.task = null;
}

// --- 1. normal full run, all 9 slots, correct sequence ---
state = { task: { kind: 'toss', slot: 0, totalSlots: 9 } };
calls = []; throwOnCall = null;
await runToss();
const expectedPerSlot = (n) => [`key ${n}`, 'key left.control -indefinite', 'key q', 'key left.control -release'];
let expected = [];
for (let i = 1; i <= 9; i++) expected.push(...expectedPerSlot(i));
const pass1 = JSON.stringify(calls) === JSON.stringify(expected) && state.task === null;
console.log('1. full 9-slot run correct sequence + task cleared ->', pass1 ? 'PASS' : 'FAIL', pass1 ? '' : JSON.stringify(calls));

// --- 2. cancel mid-run via /stop (simulate: external code sets state.task=null after slot 3) ---
state = { task: { kind: 'toss', slot: 0, totalSlots: 9 } };
calls = []; throwOnCall = null;
const p = runToss();
// simulate /stop firing after a tick (task starts null-check at top of each loop iter)
setTimeout(() => { state.task = null; }, 0);
await p;
const stoppedEarly = calls.length < expected.length;
console.log('2. mid-run cancel stops early ->', stoppedEarly ? 'PASS' : 'FAIL', 'calls made:', calls.length);

// --- 3. error mid-slot -> ctrl release still attempted, loop breaks (no stuck-held ctrl) ---
state = { task: { kind: 'toss', slot: 0, totalSlots: 9 } };
calls = []; throwOnCall = 2; // fails on the 2nd sendConsole call (the ctrl -indefinite one)
