const stoppedAfterError = !calls.includes('key 2'); // never reached slot 2
console.log('3. error mid-slot -> ctrl release attempted:', hasReleaseAfterError, ' loop broke (no slot 2):', stoppedAfterError, (hasReleaseAfterError && stoppedAfterError) ? 'PASS' : 'FAIL');
console.log('   calls:', JSON.stringify(calls));
