// single `key q` drops one item, and Ctrl-held + `key q` drops the whole
// stack -- but ONLY if the Ctrl hold is given real time to register before Q
// fires. Back-to-back with no delay silently degrades Ctrl+Q into a single-
// item drop (proven both ways, live) -- the wait below is load-bearing, not
// decorative.
function sleep(ms) { return new Promise((resolve) => setTimeout(resolve, ms)); }

const TOSS_HOTBAR_SLOTS = 9;
// FIELD-CORRECTION, same day: the first live 9-slot sweep at 300/1500/500ms
// was UNRELIABLE -- 4 of 9 slots got zero effect, 3 more only single-item-
// dropped instead of the proven full-stack Ctrl+Q (RCON before/after on
// BariBrute confirmed this precisely, not assumed). The single manually-
// paced proof-of-concept on BariThak that validated the RECIPE had many
// real seconds of human curl-call overhead between each raw command that
// this back-to-back automated loop doesn't get for free -- bumped every gap
// well past that once-working pace. Still unverified whether this is enough
// under sustained automated load; the wrapper has no RCON (LAW, see header)
// so it cannot self-verify a drop landed and retry -- a caller must ground-
// truth this like the live tests did.
const TOSS_SELECT_SETTLE_MS = 800;  // let the hotbar-select land before holding ctrl
const TOSS_CTRL_HOLD_MS = 1500;     // proven-live gap between ctrl-hold and Q
const TOSS_BETWEEN_SLOTS_MS = 1200; // let one slot's release fully land before the next

async function runToss() {
  for (let slot = 1; slot <= TOSS_HOTBAR_SLOTS; slot++) {
    if (state.task?.kind !== 'toss') return; // /stop or a new task superseded this run
    state.task = { kind: 'toss', slot, totalSlots: TOSS_HOTBAR_SLOTS, at: Date.now() };
    try {
      sendConsole(`key ${slot}`);
      await sleep(TOSS_SELECT_SETTLE_MS);
      sendConsole('key left.control -indefinite');
      await sleep(TOSS_CTRL_HOLD_MS);
      sendConsole('key q');
      sendConsole('key left.control -release');
    } catch (e) {
      log(`toss: aborted on hotbar slot ${slot}: ${e.message}`);
      try { sendConsole('key left.control -release'); } catch {} // never leave ctrl stuck held
      break;
    }
    await sleep(TOSS_BETWEEN_SLOTS_MS);
  }
  if (state.task?.kind === 'toss') state.task = null;
}

