// FIELD-CORRECTION, same day, ROOT CAUSE FOUND: the first live 9-slot sweep
// (300/1500/500ms) was unreliable -- 4 of 9 slots got zero effect, others
// only single-item-dropped instead of the proven full-stack Ctrl+Q. Doubling
// every delay (this file's prior revision, 800/1500/1200ms) did NOT fix it,
// which ruled out plain timing as the cause. Diagnosed live via RCON
// before/after + /native `close`: an open GUI screen (menu/inventory/chest
// -- exact origin unconfirmed, plausibly left open by other driver activity)
// silently swallows hotbar-select/Q key injection, since those are normal-
// gameplay keybinds that don't mean the same thing (or anything) while a
// screen has focus. `close` immediately before the sweep fixed it -- retried
// on the previously-dead gravel slot right after and it dropped clean.
// CloseCommand.java is a no-op if nothing's open, so this is safe to always
// send, not just defensively-suspected-needed.
const TOSS_SELECT_SETTLE_MS = 500;  // let the hotbar-select land before holding ctrl
const TOSS_CTRL_HOLD_MS = 1500;     // proven-live gap between ctrl-hold and Q
const TOSS_BETWEEN_SLOTS_MS = 800;  // let one slot's release fully land before the next

async function runToss() {
  try { sendConsole('close'); } catch {} // see ROOT CAUSE note above -- always safe, sometimes load-bearing
  await sleep(TOSS_SELECT_SETTLE_MS);
  for (let slot = 1; slot <= TOSS_HOTBAR_SLOTS; slot++) {
    if (state.task?.kind !== 'toss') return; // /stop or a new task superseded this run
    state.task = { kind: 'toss', slot, totalSlots: TOSS_HOTBAR_SLOTS, at: Date.now() };
    try {
      sendConsole(`key ${slot}`);
      await sleep(TOSS_SELECT_SETTLE_MS);
      sendConsole('key left.control -indefinite');
      await sleep(TOSS_CTRL_HOLD_MS);
      sendConsole('key q');
      sendConsole('key left.control -release');
    } catch (e) {
      log(`toss: aborted on hotbar slot ${slot}: ${e.message}`);
      try { sendConsole('key left.control -release'); } catch {} // never leave ctrl stuck held
      break;
    }
    await sleep(TOSS_BETWEEN_SLOTS_MS);
  }
  if (state.task?.kind === 'toss') state.task = null;
}

